/* Spanish translation of the AWS Certified Developer – Associate practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("aws-developer", {
  "dva1": ["Una función Lambda consume una cola SQS en lotes de 10. Cuando un mensaje falla, los 10 vuelven a la cola y se reprocesan. ¿Cómo puede el desarrollador reintentar solo los mensajes que fallaron?", ["Aumentar el visibility timeout de la cola a 12 horas para que los reintentos ocurran con menos frecuencia", "Convertir la cola estándar en una cola FIFO con deduplicación basada en contenido", "Configurar la concurrencia reservada de la función en 1 para que los lotes se ejecuten de uno en uno", "Habilitar ReportBatchItemFailures y devolver los IDs de los mensajes que fallaron"], "Con ReportBatchItemFailures la función devuelve batchItemFailures, así que Lambda elimina los mensajes exitosos y solo los mensajes indicados vuelven a ser visibles. Un visibility timeout más largo solo retrasa el mismo reintento del lote completo.", ["Un visibility timeout más largo solo retrasa el reintento; el lote completo de 10 vuelve a ser visible cuando falla un mensaje.", "FIFO con deduplicación basada en contenido evita envíos duplicados, pero sin respuestas de lote parcial un lote fallido se sigue reintentando completo.", "Una concurrencia reservada de 1 solo serializa los lotes; cada lote que falla se sigue devolviendo completo a la cola.", null]],
  "dva2": ["Una tabla de pedidos debe devolver todos los pedidos de un cliente, del más reciente al más antiguo, con una sola solicitud eficiente. ¿Qué diseño de claves es el adecuado?", ["Partition key orderDate y sort key customerId", "Partition key customerId y sort key orderDate", "Partition key orderId sin sort key", "Partition key status y sort key customerId"], "Un Query sobre la partition key customerId devuelve los ítems de ese cliente, y ScanIndexForward=false los ordena por orderDate de forma descendente. Usar solo orderId obligaría a hacer un Scan.", ["Con orderDate como partition key, los pedidos de un cliente quedan repartidos en muchos valores de partición y no se pueden obtener con un solo Query.", null, "Con solo orderId como clave, encontrar los pedidos de un cliente requiere un Scan, y no hay sort key para ordenar por fecha.", "Una partition key status agrupa los pedidos por estado, no por cliente, y una clave de baja cardinalidad como status además crea particiones calientes."]],
  "dva3": ["Una tabla de DynamoDB ya existe y contiene datos. Ahora el equipo necesita consultar ítems por un atributo email que no forma parte de la primary key. ¿Qué deben agregar?", ["Un local secondary index con email como sort key", "Un trigger de DynamoDB Streams sobre la tabla", "Un global secondary index con email como partition key", "Un segundo atributo llamado email en la primary key de la tabla"], "Los GSI se pueden agregar a una tabla existente y pueden usar cualquier atributo como nueva partition key. Los LSI solo se pueden definir al crear la tabla y deben compartir la partition key de la tabla.", ["Un LSI solo se puede crear junto con la tabla y debe reutilizar la partition key de la tabla, así que no se puede agregar ahora ni usar email como clave.", "Streams captura los cambios de los ítems para procesarlos; no ofrece una forma de consultar ítems por email.", null, "La primary key de una tabla no se puede cambiar después de crearla; habría que crear una tabla nueva y migrar los datos."]],
  "dva4": ["¿Qué operación de lectura de DynamoDB no puede usar lecturas fuertemente consistentes?", ["Un Query sobre un global secondary index", "Un GetItem sobre la tabla base", "Un Query sobre un local secondary index", "Un Scan de la tabla base"], "Los GSI se actualizan de forma asíncrona y solo admiten lecturas eventualmente consistentes. Las lecturas de la tabla base y los Query sobre LSI pueden solicitar ConsistentRead=true.", [null, "GetItem sobre la tabla base admite ConsistentRead=true, así que ahí sí hay lecturas fuertemente consistentes.", "Los LSI comparten la partición de la tabla base y admiten lecturas fuertemente consistentes cuando se establece ConsistentRead=true.", "Un Scan de la tabla base también puede solicitar ConsistentRead=true, así que sí admite consistencia fuerte."]],
  "dva5": ["Una aplicación realiza 10 lecturas fuertemente consistentes por segundo de ítems de 6 KB cada uno. ¿Cuántas read capacity units necesita la tabla?", ["20", "10", "15", "60"], "Una RCU cubre una lectura fuertemente consistente por segundo de hasta 4 KB. 6 KB se redondea hacia arriba a 8 KB, lo que equivale a 2 RCU por lectura, así que 10 lecturas necesitan 20. Con lecturas eventualmente consistentes se necesitarían 10.", [null, "10 RCU alcanzarían para ítems de 6 KB solo con lecturas eventualmente consistentes; las lecturas fuertemente consistentes de 6 KB necesitan 2 RCU cada una.", "15 sale de dividir 6 KB entre 4 KB sin redondear hacia arriba; la capacidad se cobra en unidades completas de 4 KB, así que cada lectura cuesta 2 RCU.", "60 trata las RCU como unidades de 1 KB (el tamaño de la unidad de escritura); las unidades de lectura son de 4 KB, así que 6 KB necesita 2 RCU por lectura."]],
  "dva6": ["Una aplicación escribe 12 ítems por segundo en DynamoDB y cada ítem mide 2.5 KB. ¿Cuántas write capacity units se requieren?", ["30", "36", "12", "24"], "Una WCU cubre una escritura por segundo de hasta 1 KB. 2.5 KB se redondea hacia arriba a 3 KB, así que son 3 WCU por escritura; multiplicado por 12 escrituras da 36.", ["30 usa 2.5 KB sin redondear hacia arriba; cada escritura se cobra en unidades completas de 1 KB, así que 2.5 KB cuesta 3 WCU.", null, "12 solo alcanzaría para ítems de 1 KB o menos; un ítem de 2.5 KB necesita 3 WCU por escritura.", "24 redondea 2.5 KB hacia abajo a 2 KB; DynamoDB siempre redondea el tamaño del ítem hacia arriba, en este caso a 3 KB."]],
  "dva7": ["Dos usuarios editan el mismo ítem de DynamoDB al mismo tiempo, y el cambio de uno sobrescribe en silencio el del otro. ¿Cómo debe el desarrollador evitar las actualizaciones perdidas?", ["Cambiar todas las lecturas de la aplicación al modo eventualmente consistente", "Agregar un global secondary index sobre un atributo de versión y consultarlo primero", "Activar DynamoDB Streams y reproducir desde el stream los cambios perdidos", "Guardar un número de versión y agregar una condition expression que lo verifique al escribir"], "El bloqueo optimista compara la versión esperada en una ConditionExpression; si otro escritor la cambió antes, la escritura falla con ConditionalCheckFailedException en lugar de sobrescribir.", ["La consistencia de lectura afecta qué tan reciente es una lectura, no si una escritura posterior sobrescribe otra concurrente; las lecturas eventuales empeoran el problema.", "Un GSI sobre un atributo de versión es eventualmente consistente y es una lectura aparte, así que la condición de carrera entre lectura y escritura sigue existiendo.", "Streams registra los cambios después de que ocurren; reproducirlos no evita la sobrescritura ni puede decidir qué edición debe prevalecer.", null]],
  "dva8": ["Una función Lambda abre una nueva conexión a la base de datos y carga un archivo de configuración grande en cada invocación, lo que agrega latencia. ¿Qué cambio ayuda MÁS?", ["Aumentar el timeout de la función a 15 minutos para que la inicialización tenga tiempo de terminar", "Copiar el archivo de configuración a la carpeta /tmp de la función al inicio de cada llamada", "Crear la conexión y cargar la configuración fuera del handler para reutilizarlas", "Invocar la función de forma asíncrona para que quienes la llaman no esperen la inicialización"], "El código fuera del handler se ejecuta una vez por entorno de ejecución y lo reutilizan las invocaciones en caliente. Un timeout más largo o la invocación asíncrona no eliminan el trabajo de inicialización repetido.", ["Un timeout más largo permite que la inicialización lenta termine, pero se sigue repitiendo en cada invocación, así que la latencia no cambia.", "Copiar el archivo a /tmp en cada llamada sigue siendo trabajo repetido; /tmp persiste en entornos calientes, pero solo el código fuera del handler evita rehacerlo.", null, "La invocación asíncrona oculta la latencia a quien llama, pero la función sigue repitiendo la misma inicialización en cada ejecución y cuesta la misma duración."]],
  "dva9": ["Un proceso batch nocturno tarda unos 40 minutos en ejecutarse en un solo proceso. El equipo quiere una opción serverless sin servidores que administrar. ¿Dónde debe ejecutarse?", ["Una sola función Lambda con el timeout máximo", "Una REST API de API Gateway con integración Lambda", "Una función Lambda@Edge en CloudFront", "Una tarea de Amazon ECS en AWS Fargate"], "Las funciones Lambda se detienen después de 15 minutos como máximo, así que un proceso único de 40 minutos no cabe. Fargate ejecuta contenedores durante el tiempo que sea necesario sin administrar instancias EC2.", ["El timeout máximo de Lambda es de 15 minutos, así que un proceso único de 40 minutos se detendría a la mitad.", "Las integraciones de API Gateway expiran a los 29 segundos aproximadamente de forma predeterminada, y la Lambda detrás sigue limitada a 15 minutos.", "Lambda@Edge tiene límites aún más estrictos (segundos, no minutos) y está pensada para procesar solicitudes y respuestas en CloudFront, no para procesos batch.", null]],
  "dva10": ["Un evento de S3 invoca una función Lambda de forma asíncrona. Los eventos que siguen fallando después de los reintentos integrados de Lambda se están perdiendo. ¿Qué debe configurar el desarrollador?", ["Configurar un destino on-failure o una dead-letter queue", "Aumentar la memoria de la función para que los reintentos tengan más probabilidad de éxito", "Configurar provisioned concurrency para que cada evento tenga un entorno caliente", "Reducir la antigüedad máxima del evento a 60 segundos para que las fallas se reporten antes"], "En las invocaciones asíncronas, Lambda reintenta dos veces de forma predeterminada y luego descarta el evento, a menos que haya un destino on-failure o una DLQ configurados. Una antigüedad de evento menor haría que los eventos se descarten aún antes.", [null, "Más memoria puede ayudar a que algunos reintentos tengan éxito, pero los eventos que siguen fallando después de los reintentos se descartan igual si no hay destino ni DLQ.", "Provisioned concurrency reduce los cold starts; no hace nada para capturar los eventos cuyo procesamiento falla.", "Reducir la antigüedad máxima del evento hace que Lambda descarte los eventos antes; sin destino ni DLQ se siguen perdiendo."]],
  "dva11": ["Una función Lambda conectada a subredes privadas de una VPC debe llamar a una API pública de un tercero en internet. ¿Qué se requiere?", ["Una dirección IP pública asignada a las elastic network interfaces de la función", "Una ruta hacia un internet gateway agregada directamente a la tabla de rutas de las subredes privadas", "Un NAT gateway en una subred pública, con ruta desde las subredes privadas", "Un VPC gateway endpoint que apunte al nombre de dominio de la API del tercero"], "Las ENI de Lambda en una VPC nunca reciben IP pública, así que el acceso saliente a internet pasa por un NAT gateway. Los gateway endpoints existen solo para S3 y DynamoDB. Ten en cuenta que los NAT gateways se cobran por hora.", ["Las elastic network interfaces de Lambda en una VPC nunca reciben direcciones IP públicas, y no se les puede asignar una.", "Una ruta hacia un internet gateway vuelve públicas las subredes, pero las ENI de la función siguen sin IP pública, así que el tráfico no puede salir.", null, "Los gateway endpoints existen solo para S3 y DynamoDB; no pueden llegar a APIs arbitrarias de terceros en internet."]],
  "dva12": ["Doce funciones Lambda usan la misma biblioteca interna de logging. ¿Cómo puede el equipo compartirla sin incluir una copia en cada paquete de despliegue?", ["Guardar el código de la biblioteca en una variable de entorno que lea cada función", "Publicar la biblioteca como una Lambda layer y adjuntarla a cada función", "Descargar la biblioteca en la carpeta /tmp de cada función en cada cold start", "Ejecutar la biblioteca como un estado aparte en una state machine de AWS Step Functions"], "Las layers empaquetan una sola vez bibliotecas o runtimes compartidos y se adjuntan a muchas funciones. Las variables de entorno contienen cadenas pequeñas, no código.", ["Las variables de entorno están limitadas a 4 KB en total y están pensadas para cadenas de configuración, no para código de bibliotecas.", null, "Descargarla en cada cold start agrega latencia y una dependencia externa, y además sigue habiendo una copia por función; las layers resuelven esto directamente.", "Step Functions orquesta tareas separadas; una biblioteca de logging debe ejecutarse dentro del proceso de cada función, no como un estado del workflow."]],
  "dva13": ["Un desarrollador quiere un workflow que cobre una tarjeta, espere (posiblemente durante días) a que una persona apruebe un reembolso y luego continúe, con reintentos en cada paso. ¿Qué servicio es el MÁS adecuado?", ["Una sola función Lambda que haga polling en un bucle", "Una cola SQS estándar con un visibility timeout largo", "Amazon EventBridge con una regla programada", "AWS Step Functions con un callback de task token"], "Los Standard workflows de Step Functions pueden pausarse en una tarea .waitForTaskToken hasta que se llame a SendTaskSuccess, y ofrecen retry y catch por estado. Una Lambda que hace polling llegaría al límite de 15 minutos.", ["Una sola función Lambda se detiene después de 15 minutos, así que no puede esperar días, y hacer polling en un bucle desperdicia cómputo.", "El visibility timeout de SQS llega como máximo a 12 horas y una cola no tiene lógica de workflow, reintentos por paso ni callbacks de aprobación.", "Una regla programada de EventBridge se ejecuta con un temporizador; no lleva el estado del workflow ni se pausa hasta que una persona responda.", null]],
  "dva14": ["Cuando se registra un pedido, tres servicios independientes (facturación, envíos y analítica) deben recibir y procesar cada evento de pedido. ¿Qué diseño es el MÁS apropiado?", ["Enviar cada pedido a una sola cola SQS que consulten los tres servicios", "Escribir cada pedido en un bucket de S3 y que cada servicio liste el bucket", "Publicar en un tema SNS con una cola SQS suscrita por cada servicio", "Invocar los tres servicios uno tras otro desde el productor"], "El fan-out de SNS a SQS entrega una copia de cada mensaje a cada cola suscrita, así que cada servicio procesa todos los eventos a su propio ritmo. Con una sola cola compartida, cada mensaje llegaría a un solo consumidor.", ["Con una sola cola compartida, cada mensaje se entrega a uno solo de los consumidores que compiten, así que cada servicio se perdería la mayoría de los pedidos.", "Listar un bucket es lento, no lleva seguimiento de entregas y obliga a cada servicio a averiguar qué objetos ya procesó.", null, "Invocar los servicios en secuencia acopla el productor a los tres, y una falla o lentitud en uno bloquea o rompe a los demás."]],
  "dva15": ["Una cola SQS FIFO transporta actualizaciones de muchos clientes. Las actualizaciones deben mantener el orden por cliente, pero clientes distintos deben procesarse en paralelo. ¿Qué debe establecer el productor?", ["El MessageDeduplicationId con el ID del cliente", "El MessageGroupId con el ID del cliente", "DelaySeconds con un valor distinto para cada cliente", "Una cola FIFO separada para cada mensaje"], "El orden FIFO se mantiene dentro de un grupo de mensajes, y los grupos distintos se pueden consumir en paralelo. El ID de deduplicación solo evita duplicados dentro de la ventana de 5 minutos.", ["El ID de deduplicación suprime los mensajes repetidos con el mismo ID durante 5 minutos, así que usar el ID del cliente descartaría las actualizaciones posteriores de ese cliente.", null, "DelaySeconds solo pospone la entrega; las colas FIFO solo admiten un retraso a nivel de cola, y no tiene efecto en el orden por cliente ni en el paralelismo.", "Una cola por mensaje es inmanejable y pierde el orden entre los mensajes de un cliente; los grupos de mensajes hacen esto dentro de una sola cola."]],
  "dva16": ["Un consumidor consulta una cola SQS en un bucle cerrado y recibe muchas respuestas vacías, lo que aumenta el costo. ¿Qué debe cambiar el desarrollador?", ["Habilitar long polling con un tiempo de espera de recepción de hasta 20 segundos", "Reducir el periodo de retención de mensajes de la cola para tener menos mensajes", "Reducir el visibility timeout a 0 segundos para que los mensajes regresen más rápido", "Convertir la cola en FIFO para que los mensajes se entreguen en lotes"], "El long polling espera a que lleguen mensajes antes de responder, lo que reduce las recepciones vacías y los cargos por solicitud. El visibility timeout y la retención no afectan las consultas vacías.", [null, "La retención controla cuánto tiempo se guardan los mensajes no consumidos; no reduce las respuestas vacías al consultar una cola vacía.", "Un visibility timeout de 0 hace que los mensajes en proceso reaparezcan de inmediato y causa duplicados; no reduce las recepciones vacías.", "Las colas FIFO cambian el orden y la deduplicación; con short polling siguen devolviendo respuestas vacías."]],
  "dva17": ["Los mensajes de una cola SQS a veces se procesan dos veces. Procesar un mensaje tarda unos 90 segundos, y el visibility timeout de la cola es de 30 segundos. ¿Cuál es la solución MÁS probable?", ["Habilitar long polling en la cola para que los consumidores esperen mensajes nuevos", "Aumentar el periodo de retención de mensajes al máximo de 14 días", "Subir el visibility timeout por encima del tiempo típico de procesamiento", "Agregar un retraso de entrega de 60 segundos a cada mensaje que envía el productor"], "Si el procesamiento dura más que el visibility timeout, el mensaje vuelve a ser visible y otro consumidor lo toma. Configurar un timeout mayor que el tiempo de procesamiento (o extenderlo con ChangeMessageVisibility) lo evita.", ["El long polling reduce las recepciones vacías; no impide que un mensaje reaparezca mientras todavía se está procesando.", "La retención decide cuánto tiempo se guardan los mensajes sin procesar, lo cual no tiene relación con los duplicados causados por un visibility timeout corto.", null, "Un retraso de entrega solo afecta cuándo un mensaje nuevo se vuelve visible por primera vez; después de recibirlo, el visibility timeout de 30 segundos sigue expirando a mitad del procesamiento."]],
  "dva18": ["Una función Lambda de limpieza debe ejecutarse todas las noches a las 02:00 UTC. ¿Cuál es la forma más sencilla de dispararla?", ["Un schedule de Amazon EventBridge con una expresión cron", "Una delay queue de SQS con un retraso de 24 horas", "Una alarma de CloudWatch sobre la métrica Invocations de la función", "Una regla de lifecycle de S3 que invoque Lambda"], "EventBridge Scheduler (o una regla programada) invoca destinos según expresiones cron o rate. Los retrasos de SQS tienen un máximo de 15 minutos.", [null, "Las delay queues de SQS tienen un máximo de 15 minutos, así que un retraso de 24 horas no es posible, y tampoco se ejecutaría a una hora fija.", "Una alarma de CloudWatch reacciona a umbrales de métricas; no es un programador y no puede invocar Lambda directamente a una hora determinada.", "Las reglas de lifecycle de S3 hacen transiciones o expiran objetos; no pueden invocar Lambda ni ejecutarse según un horario."]],
  "dva19": ["Las llamadas al AWS SDK de una aplicación fallan ocasionalmente con ThrottlingException durante los picos de tráfico. ¿Qué debe hacer el código?", ["Reintentar de inmediato en un bucle cerrado hasta que funcione", "Reintentar con exponential backoff y jitter", "Capturar el error y descartar la solicitud", "Crear un nuevo cliente del SDK en cada reintento"], "AWS recomienda exponential backoff con jitter para que los reintentos se distribuyan y el servicio tenga tiempo de recuperarse. Los reintentos inmediatos agregan carga y empeoran el throttling.", ["Los reintentos inmediatos en un bucle cerrado agregan todavía más carga mientras el servicio ya está aplicando throttling, así que las fallas continúan.", null, "Descartar las solicitudes hace perder datos o trabajo; el throttling es un error transitorio que se debe reintentar con backoff.", "Un cliente nuevo no cambia el límite de tasa del servicio y pierde tiempo en la inicialización; la solución es espaciar los reintentos."]],
  "dva20": ["Un clickstream debe procesarse en orden por usuario, conservarse durante varios días para poder reproducirlo y ser leído por varias aplicaciones independientes. ¿Qué servicio es el adecuado?", ["Cola estándar de Amazon SQS", "Tema estándar de Amazon SNS", "Amazon SES", "Amazon Kinesis Data Streams"], "Kinesis Data Streams mantiene los registros ordenados por shard (según la partition key), los conserva para reproducirlos y permite que varios consumidores lean los mismos datos. Los mensajes de SQS se eliminan una vez consumidos.", ["Las colas estándar de SQS no garantizan el orden, y un mensaje consumido se elimina, así que no se puede reproducir ni compartir entre varias aplicaciones.", "SNS envía mensajes a los suscriptores pero no los guarda para reproducirlos, y los temas estándar no garantizan el orden.", "Amazon SES es un servicio de envío de correo electrónico y no tiene nada que ver con datos de clickstream en streaming.", null]],
  "dva21": ["¿Qué estrategia de caché actualiza la caché cada vez que se escribe en la base de datos, de modo que las lecturas nunca están desactualizadas, a costa de guardar en caché datos que quizá nunca se lean?", ["Write-through", "Lazy loading", "Solo time-to-live", "Read replica"], "Write-through escribe en la caché junto con la base de datos. Lazy loading llena la caché solo cuando hay un miss, así que guarda solo los datos solicitados pero puede servir valores desactualizados.", [null, "Lazy loading llena la caché solo cuando hay un miss de lectura, así que guarda solo los datos solicitados y puede servir valores desactualizados después de las escrituras.", "Un TTL solo expira las entradas después de un tiempo determinado; no actualiza la caché cuando se escribe en la base de datos.", "Una read replica es una copia de la base de datos para escalar lecturas; no es una estrategia de caché y puede quedar atrasada respecto del primario."]],
  "dva22": ["Una tabla de DynamoDB guarda sesiones web que deben desaparecer 24 horas después de su creación sin ningún código de limpieza. ¿Qué debe usar el desarrollador?", ["Un Scan nocturno que elimine los ítems viejos con llamadas BatchWriteItem", "Un global secondary index sobre el atributo de fecha de creación de la sesión", "DynamoDB Accelerator (DAX) con una vida de caché de ítems de 24 horas", "DynamoDB TTL sobre un atributo que contenga la marca de tiempo de expiración"], "TTL elimina los ítems después de que pasa la hora epoch del atributo elegido, sin costo extra de escritura. Un proceso de Scan y eliminación funciona, pero consume capacidad y requiere código.", ["Un proceso nocturno de Scan y eliminación funciona, pero requiere código, consume capacidad de lectura y escritura y elimina los ítems hasta con un día de retraso.", "Un GSI solo permite consultar por fecha de creación; no elimina nada, así que seguiría haciendo falta código de limpieza.", "DAX guarda en caché las lecturas delante de la tabla; una vida de caché no elimina ítems de DynamoDB.", null]],
  "dva23": ["Cada vez que cambia un ítem en una tabla de DynamoDB, una función Lambda debe enviar una notificación que incluya los valores anteriores y los nuevos. ¿Qué debe configurar el desarrollador?", ["Un trail de CloudTrail que registre los data events de DynamoDB para la tabla", "DynamoDB Streams (imágenes nuevas y anteriores) con un trigger de Lambda", "Una función Lambda programada que haga Scan de toda la tabla cada minuto", "Un tema SNS suscrito directamente a las notificaciones de cambios de la tabla"], "Streams registra cada cambio de ítem, y el tipo de vista NEW_AND_OLD_IMAGES incluye ambas versiones; Lambda consulta el stream mediante un event source mapping.", ["Los data events de CloudTrail registran quién llamó a qué API, no los valores anteriores y nuevos de los atributos del ítem, y no son un trigger push para Lambda.", null, "Un Scan completo por minuto es caro, se pierde los cambios intermedios y nunca ve los valores anteriores del ítem.", "DynamoDB no puede publicar notificaciones de cambios directamente en un tema SNS; los cambios a nivel de ítem se exponen mediante Streams."]],
  "dva24": ["Una aplicación sube archivos de video de 3 GB a S3 y de vez en cuando tiene que reiniciar toda la carga después de una falla momentánea de red. ¿Qué debe usar?", ["Una sola llamada PutObject con un timeout más largo", "S3 Transfer Acceleration sin cambiar el método de carga", "Multipart upload, reintentando solo las partes que fallaron", "S3 Object Lock en modo governance"], "Multipart upload envía las partes en paralelo y permite reintentar una parte fallida por sí sola; AWS lo recomienda a partir de unos 100 MB y es obligatorio por encima de 5 GB. Transfer Acceleration puede acelerar la ruta, pero un PUT único sigue reiniciándose.", ["Un solo PutObject está limitado a 5 GB y una falla de red sigue obligando a reiniciar toda la carga de 3 GB, sin importar el timeout.", "Transfer Acceleration puede acelerar la ruta de red, pero un PUT único que falla tiene que empezar de cero.", null, "Object Lock impide que los objetos se eliminen o sobrescriban; no hace nada para que las cargas se puedan reanudar."]],
  "dva25": ["Un reporte ejecuta un Scan con una FilterExpression sobre customerId, que es la partition key de la tabla, y resulta lento y caro. ¿Cuál es el MEJOR enfoque?", ["Aumentar el tamaño de página del Scan", "Usar un Scan paralelo con más segmentos", "Usar un Query con una key condition sobre customerId", "Agregar también una FilterExpression sobre otro atributo"], "Un Scan lee todos los ítems y filtra después, consumiendo capacidad por toda la tabla. Un Query sobre la partition key lee solo los ítems que coinciden.", ["Un tamaño de página mayor solo cambia cuántos ítems vuelven por llamada; el Scan sigue leyendo y cobrando toda la tabla.", "Un Scan paralelo termina antes, pero sigue leyendo todos los ítems y usa todavía más capacidad a la vez.", null, "Los filtros se aplican después de leer los ítems, así que otra FilterExpression no reduce la capacidad consumida."]],
  "dva26": ["Una aplicación de DynamoDB con muchas lecturas necesita latencia de lectura de microsegundos para lecturas repetidas de los mismos ítems, sin cambiar mucho su código de acceso a datos. ¿Qué debe agregar el desarrollador?", ["DynamoDB Accelerator (DAX)", "Una global table de DynamoDB", "Un bucket de S3 delante de la tabla", "DynamoDB Streams"], "DAX es una caché en memoria compatible con la API de DynamoDB que sirve las lecturas repetidas en microsegundos. Las global tables replican entre regiones para disponibilidad, no para caché.", [null, "Las global tables replican datos entre regiones para disponibilidad y escrituras locales; no agregan una caché en memoria.", "S3 es almacenamiento de objetos con latencia de milisegundos y obligaría a reescribir el código de acceso a datos; no es una caché de DynamoDB.", "Streams entrega un registro de los cambios de ítems para procesarlos; no acelera las lecturas."]],
  "dva27": ["Una REST API de API Gateway con integración Lambda proxy devuelve 502 Bad Gateway. La función devuelve la cadena simple \"OK\". ¿Cuál es el problema?", ["Habilitar CORS en el método para que los navegadores acepten la respuesta simple", "Devolver un objeto con statusCode, headers y un body de tipo string", "Subir el timeout de la función por encima del límite de integración de 29 segundos", "Agregar un mapping template que envuelva la cadena en un objeto JSON"], "Con la integración proxy, API Gateway espera un objeto JSON que contenga statusCode y body (el body como string). Cualquier otra forma es una respuesta de Lambda mal formada, que se convierte en un 502.", ["CORS solo controla qué orígenes del navegador pueden leer una respuesta; no corrige la respuesta proxy mal formada que API Gateway convierte en un 502.", null, "Un timeout produciría un 504, no un 502, y la función ya responde rápido; el problema es la forma de lo que devuelve.", "Las integraciones proxy pasan la solicitud y la respuesta sin mapping templates, así que API Gateway sigue exigiendo statusCode y body de la función."]],
  "dva28": ["Una cola SQS estándar puede entregar el mismo mensaje más de una vez. ¿Cómo debe diseñarse el consumidor que cobra a los clientes?", ["Hacerlo idempotente guardando cada ID de solicitud y omitiendo las repeticiones", "Eliminar cada mensaje apenas se recibe, antes de cobrar la tarjeta", "Configurar el visibility timeout en 0 segundos para que los duplicados aparezcan de inmediato", "Cambiar las lecturas de base de datos del consumidor al modo fuertemente consistente"], "Las colas estándar garantizan entrega at-least-once, así que los consumidores deben tolerar duplicados, por ejemplo con una escritura condicional sobre un ID de solicitud. Eliminar primero arriesga perder el mensaje si el procesamiento falla.", [null, "Eliminar antes de procesar significa que una caída a mitad del cobro pierde el mensaje por completo, y aun así no evita que se cobre una entrega duplicada.", "Un visibility timeout de cero hace que los mensajes reaparezcan de inmediato mientras aún se procesan, lo que causa más cobros duplicados, no menos.", "La consistencia de lectura afecta qué tan recientes son las lecturas de la base de datos; no evita que el mismo mensaje de SQS se entregue y se cobre dos veces."]],
  "dva29": ["Una función Lambda necesita leer ítems de una tabla de DynamoDB. ¿Cómo debe obtener los permisos?", ["Guardar las access keys de un usuario IAM en las variables de entorno de la función", "Agregar una política de tabla que permita a cualquier principal de la cuenta leer la tabla", "Un execution role cuya política permita acciones de lectura sobre esa única tabla", "Adjuntar la política administrada AdministratorAccess al rol de la función"], "Lambda asume su execution role y obtiene credenciales temporales automáticamente; limitar la política a la tabla sigue el principio de mínimo privilegio. Las keys de larga duración de un usuario IAM son un riesgo e innecesarias.", ["Las keys de larga duración de un usuario IAM pueden filtrarse y deben rotarse a mano; Lambda ya obtiene credenciales temporales de su execution role.", "Abrir la tabla a todos los principals de la cuenta rompe el mínimo privilegio, y la función igual necesita una identidad para hacer las llamadas.", null, "AdministratorAccess funcionaría, pero otorga mucho más que leer una tabla, lo que viola el mínimo privilegio."]],
  "dva30": ["Una aplicación en una instancia EC2 debe subir archivos a un bucket de S3. ¿Cuál es la forma recomendada de darle credenciales?", ["Guardar las access keys de un usuario IAM en ~/.aws/credentials en la instancia", "Adjuntar un rol IAM a la instancia mediante un instance profile", "Escribir las access keys directamente en el código fuente de la aplicación", "Hacer público el bucket para que no se necesiten credenciales"], "Un instance profile entrega credenciales de rol temporales y rotadas automáticamente a través del instance metadata service, y el SDK las encuentra sin cambios de código.", ["Las access keys guardadas en la instancia son secretos de larga duración que pueden filtrarse y deben rotarse manualmente; un rol de instancia las evita.", null, "Las keys escritas en el código terminan en el control de versiones y en los builds, y son la forma más común en que se filtran credenciales.", "Hacer público el bucket expone sus datos a cualquiera, y las cargas necesitarían acceso público de escritura, lo que viola el mínimo privilegio."]],
  "dva31": ["Los usuarios de una app móvil inician sesión con un user pool de Cognito. Luego la app necesita credenciales temporales de AWS para subir fotos directamente a S3. ¿Qué proporciona esas credenciales?", ["El access token del user pool, enviado a S3 en lugar de una firma SigV4", "Un usuario IAM separado con sus propias access keys para cada usuario móvil", "Un identity pool de Cognito que intercambia el token del user pool por credenciales de un rol", "Una API key de API Gateway que la app incluye en sus solicitudes de carga a S3"], "Los user pools autentican a los usuarios y emiten JWT; los identity pools federan esas identidades en credenciales temporales de AWS para un rol IAM. S3 no acepta directamente los tokens del user pool.", ["S3 solo acepta solicitudes firmadas con SigV4 y credenciales de AWS; un access token del user pool es un JWT que S3 no entiende.", "Un usuario IAM por cada usuario móvil no escala (IAM tiene cuotas de usuarios) y deja keys de larga duración en los dispositivos.", null, "Las API keys identifican clientes para los usage plans de API Gateway; S3 no las usa y no son credenciales de AWS."]],
  "dva32": ["Una REST API en API Gateway debe aceptar solo solicitudes de usuarios que iniciaron sesión en un user pool de Cognito existente, con la menor cantidad de código personalizado. ¿Qué debe configurar el desarrollador?", ["Un Cognito user pool authorizer en los métodos de la API", "Un Lambda authorizer que valide el JWT", "Autorización IAM con firma SigV4", "Una API key obligatoria en cada método"], "Un Cognito user pool authorizer valida el token del user pool sin código personalizado. Un Lambda authorizer también funcionaría, pero requiere escribir y mantener la lógica de validación.", [null, "Un Lambda authorizer podría validar el JWT, pero requiere escribir y mantener código personalizado, que es lo que la pregunta quiere evitar.", "La autorización IAM necesita credenciales de AWS y firma SigV4; iniciar sesión en el user pool no le da al cliente credenciales IAM por sí solo.", "Las API keys solo identifican clientes para los usage plans; cualquiera que tenga la key puede llamar a la API, así que no demuestran que un usuario inició sesión."]],
  "dva33": ["Una API debe validar bearer tokens emitidos por un proveedor de identidad externo que usa un formato de token personalizado y no estándar. ¿Qué función de API Gateway es la adecuada?", ["Un Lambda authorizer", "Un Cognito user pool authorizer", "Una resource policy que limite las IP de origen", "Un usage plan con throttling"], "Un Lambda authorizer ejecuta tu código para validar cualquier formato de token y devuelve una política IAM. Los Cognito authorizers solo aceptan tokens de user pools de Cognito.", [null, "Un Cognito user pool authorizer acepta solo tokens emitidos por un user pool de Cognito, no el formato personalizado de un tercero.", "Una resource policy puede restringir IP de origen, cuentas o VPC endpoints, pero no puede validar un bearer token.", "Los usage plans aplican throttling y miden a los clientes identificados por API keys; no validan tokens."]],
  "dva34": ["Un servicio de backend que se ejecuta con un rol IAM debe llamar a una API de API Gateway, y solo ese rol debe tener permiso. ¿Qué tipo de autorización debe usar la API?", ["Un Cognito user pool authorizer que verifique el ID token de quien llama", "Una API key enviada en el header x-api-key de cada solicitud", "Autorización IAM, con quienes llaman firmando las solicitudes con SigV4", "Sin autorización en la API, con una regla de AWS WAF en el stage"], "La autorización IAM verifica la firma SigV4 contra las políticas IAM, así que el acceso se puede limitar a un rol específico. Las API keys identifican clientes para los usage plans y no son un mecanismo de autorización.", ["Los Cognito authorizers validan tokens de user pool de usuarios finales; un servicio de backend con un rol IAM no tiene token de user pool.", "Las API keys identifican clientes para los usage plans; se pueden compartir o filtrar y no demuestran que quien llama sea un rol IAM específico.", null, "Dejar la API sin autenticación permite que cualquiera la llame; WAF filtra patrones de tráfico pero no autentica un rol IAM."]],
  "dva35": ["Una aplicación en la cuenta A debe escribir en una tabla de DynamoDB de la cuenta B. ¿Cuál es el enfoque recomendado?", ["Un usuario IAM en la cuenta B cuyas access keys se copian a la cuenta A", "El usuario root de la cuenta A agregado a un grupo de administradores en la cuenta B", "Una resource policy de la tabla en la cuenta B que permita escribir a cualquier principal", "Un rol en la cuenta B que confíe en la cuenta A, asumido con sts:AssumeRole"], "El acceso entre cuentas usa un rol cuya trust policy nombra a la cuenta A; quien llama también necesita permiso sts:AssumeRole y recibe credenciales temporales. No se recomienda compartir keys de larga duración.", ["Copiar keys de larga duración de un usuario IAM entre cuentas es un riesgo de seguridad y requiere rotación manual; los roles dan credenciales temporales.", "El usuario root nunca debe usarse para aplicaciones, y los usuarios root no se pueden agregar a grupos IAM de otra cuenta.", "Una política que permita escribir a cualquier principal abriría la tabla a todos, no solo a la cuenta A, lo que rompe el mínimo privilegio.", null]],
  "dva36": ["Una aplicación usa una contraseña de base de datos de Amazon RDS que debe rotarse automáticamente cada 30 días con el mínimo trabajo personalizado. ¿Dónde debe guardarse la contraseña?", ["Systems Manager Parameter Store como parámetro String", "AWS Secrets Manager con la rotación habilitada", "Una variable de entorno cifrada en la función Lambda", "Un archivo de texto en un bucket privado de S3"], "Secrets Manager tiene rotación integrada para credenciales de RDS. Parameter Store puede guardar SecureStrings pero no tiene rotación integrada, así que tendrías que construirla tú.", ["Un parámetro String simple no está cifrado, y Parameter Store no tiene rotación integrada para contraseñas de RDS.", null, "Las variables de entorno de Lambda no tienen función de rotación; tendrías que actualizar y volver a desplegar el valor tú mismo.", "Un archivo en S3 no tiene rotación, y la aplicación tendría que descargarlo e interpretarlo; no es un almacén de secretos."]],
  "dva37": ["Un equipo necesita guardar configuraciones de funcionalidades y algunos endpoints de API cifrados que nunca rotan, al menor costo. ¿Qué deben usar?", ["AWS Secrets Manager, con un secreto separado creado para cada valor", "Parámetros estándar de Parameter Store, con SecureString para los valores sensibles", "Ítems de Amazon DynamoDB cifrados en el cliente con el Encryption SDK", "Una customer managed key de AWS KMS separada que guarde cada valor de configuración"], "Los parámetros estándar de Parameter Store no tienen cargo extra de almacenamiento y SecureString cifra con KMS. Secrets Manager cobra por secreto por mes y principalmente agrega rotación, que aquí no se necesita.", ["Secrets Manager cobra por secreto por mes y principalmente agrega rotación, que estos valores estáticos no necesitan.", null, "Cifrar ítems en DynamoDB con el Encryption SDK funciona, pero agrega código y costos de tabla que Parameter Store evita.", "Las keys de KMS cifran datos; no guardan valores de configuración, y cada customer managed key cuesta alrededor de 1 dólar por mes."]],
  "dva38": ["Una aplicación debe cifrar archivos de 50 MB con una key de KMS. La llamada a la API Encrypt de KMS falla por el tamaño del payload. ¿Qué debe hacer el desarrollador?", ["Dividir el archivo en fragmentos de 4 KB y llamar a la API Encrypt de KMS para cada fragmento", "Pedir a AWS Support que aumente el límite de payload de Encrypt para la cuenta", "Usar GenerateDataKey y cifrar el archivo localmente con la data key", "Guardar el archivo sin cifrar y usar KMS para cifrar solo la key del objeto de S3"], "KMS Encrypt acepta como máximo 4 KB. El envelope encryption usa una data key para cifrar los datos localmente y guarda solo la key envuelta, que KMS puede descifrar después.", ["Dividir en llamadas de 4 KB funcionaría, pero es lento, caro y propenso al throttling; el envelope encryption es el patrón previsto.", "El límite de 4 KB de Encrypt es un límite fijo del servicio, no una cuota ajustable que Support pueda aumentar.", null, "Cifrar solo el nombre de la key del objeto deja el contenido del archivo en texto plano, lo que no cumple el requisito."]],
  "dva39": ["Un equipo de cumplimiento quiere que cada uso de la key que cifra los objetos de S3 aparezca en CloudTrail, y quiere controlar la key policy por su cuenta. ¿Qué opción de cifrado es la adecuada?", ["SSE-KMS con una customer managed key", "SSE-S3 con keys administradas por S3", "SSE-C con keys proporcionadas en cada solicitud", "Sin cifrado del lado del servidor, confiando en TLS"], "SSE-KMS registra las llamadas a la API de KMS en CloudTrail, y una customer managed key permite que el equipo escriba la key policy. Las keys de SSE-S3 las administra por completo S3 y no tienen una key policy que tú controles.", [null, "Las keys de SSE-S3 las administra por completo S3; no hay key policy que controlar ni entradas de KMS por cada uso en CloudTrail.", "Con SSE-C, el cliente proporciona la key en cada solicitud y S3 no la guarda; no hay key policy de KMS ni registro de uso de keys de KMS.", "TLS protege los datos solo en tránsito; los objetos quedarían sin cifrar en reposo y no habría uso de keys que auditar."]],
  "dva40": ["Una aplicación escribe miles de objetos por segundo en un bucket que usa SSE-KMS y empieza a recibir errores de throttling de KMS. ¿Qué reduce las solicitudes a KMS con el menor cambio?", ["Cambiar a cifrado del lado del cliente con el Encryption SDK", "Crear una nueva key de KMS para cada objeto", "Deshabilitar el cifrado predeterminado del bucket", "Habilitar S3 Bucket Keys para el bucket"], "Una S3 Bucket Key crea una key de corta duración a nivel de bucket que S3 usa para derivar data keys, lo que reduce las llamadas a KMS y su costo.", ["El cifrado del lado del cliente con el Encryption SDK sigue llamando a KMS para obtener data keys, a menos que se agregue caché, y requiere cambios de código importantes.", "Una key por objeto multiplica la cantidad de keys y de llamadas a KMS, lo que empeora el throttling y el costo.", "Deshabilitar el cifrado predeterminado no elimina el requisito de SSE-KMS que impone la aplicación o la política, y debilitaría la protección.", null]],
  "dva41": ["Una bucket policy debe rechazar cualquier solicitud que no se envíe por HTTPS. ¿Qué condición debe usar una instrucción Deny?", ["s3:x-amz-server-side-encryption igual a AES256", "aws:SourceIp fuera del rango corporativo", "aws:SecureTransport igual a false", "s3:signatureversion igual a AWS"], "Denegar las solicitudes en las que aws:SecureTransport es false obliga a cifrar en tránsito. El header de cifrado del lado del servidor controla el cifrado en reposo, no el transporte.", ["El header de cifrado del lado del servidor rige el cifrado en reposo; no dice nada sobre si la solicitud usó HTTPS.", "aws:SourceIp restringe desde dónde vienen las solicitudes, no si están cifradas en tránsito.", null, "s3:signatureversion verifica la versión de firma (SigV2 o SigV4), no si la conexión usa TLS."]],
  "dva42": ["Una app web permite a los usuarios subir una foto de perfil directamente a un bucket privado de S3 sin darles credenciales de AWS. ¿Qué debe generar el backend?", ["Una ACL public-read en el bucket mientras dure la carga", "Un usuario IAM con access keys creado para cada usuario final", "Una signed cookie de CloudFront que otorgue acceso de lectura al bucket", "Una presigned URL de PutObject que expire después de unos minutos"], "Una presigned URL lleva el permiso de quien la firmó para una operación sobre un objeto hasta que expira, así que el bucket sigue siendo privado.", ["Una ACL public-read expone los objetos del bucket a todos y no otorga permiso de carga, así que el bucket dejaría de ser privado.", "Crear usuarios IAM y keys para los usuarios finales reparte credenciales de AWS de larga duración, que es justo lo que la app debe evitar.", "Las signed cookies otorgan acceso de lectura al contenido a través de CloudFront; no permiten que un usuario suba un objeto al bucket.", null]],
  "dva43": ["Un desarrollador está adjuntando un certificado de ACM a una distribución de CloudFront para un dominio personalizado, pero el certificado no aparece en la lista. ¿Cuál es la razón MÁS probable?", ["Los certificados de ACM no se pueden usar con CloudFront", "El certificado se solicitó en una región distinta de US East (N. Virginia)", "El certificado debe importarse, no solicitarse", "CloudFront necesita que el certificado esté guardado en Secrets Manager"], "CloudFront solo usa certificados de ACM de us-east-1. Para un endpoint regional de API Gateway o un ALB, el certificado debe estar en la misma región que el recurso.", ["Los certificados de ACM son la forma estándar de agregar un certificado TLS de dominio personalizado a CloudFront; solo tienen que estar en us-east-1.", null, "Tanto los certificados emitidos por ACM como los importados funcionan con CloudFront; no es obligatorio importarlos.", "CloudFront lee los certificados de ACM (o de IAM), no de Secrets Manager."]],
  "dva44": ["El script de un desarrollador funciona localmente porque lee access keys escritas directamente en el archivo fuente. Ahora el script se ejecutará en Lambda. ¿Cuál es la MEJOR práctica?", ["Eliminar las keys y dejar que el SDK use el execution role de la función", "Mover las mismas access keys a las variables de entorno de la función", "Cifrar las keys escritas en el código con KMS y descifrarlas en cada llamada", "Guardar las keys en un archivo de configuración incluido en el .zip de despliegue"], "La cadena de proveedores predeterminada del SDK encuentra automáticamente las credenciales del rol en Lambda, EC2 y ECS. Las keys en variables de entorno siguen siendo secretos de larga duración que pueden filtrarse.", [null, "Las variables de entorno siguen conteniendo keys de larga duración que pueden filtrarse por la consola, los logs o la configuración de la función.", "Cifrar las keys igual deja credenciales de larga duración que administrar y rotar, cuando el execution role proporciona credenciales temporales sin costo.", "Un archivo de configuración en el paquete sigue siendo un secreto de larga duración escrito en el código que cualquiera con acceso al paquete puede leer."]],
  "dva45": ["S3 debe invocar una función Lambda cuando se crean objetos, pero la notificación de eventos no se puede guardar por un error de permisos. ¿Qué falta?", ["Un permiso s3:PutBucketNotification en el execution role de la función", "Una resource-based policy en la función que permita que S3 la invoque", "Una bucket policy que otorgue a la función s3:GetObject sobre los objetos nuevos", "Cifrado SSE-KMS habilitado como cifrado predeterminado del bucket de origen"], "Los servicios que envían eventos a Lambda necesitan permiso en la resource-based policy de la función (lambda add-permission). El execution role controla lo que la función puede hacer.", ["El execution role controla lo que la función puede hacer, no quién puede invocarla; S3 necesita permiso en la resource-based policy de la función.", null, "Una bucket policy rige el acceso a los objetos; la falla es que S3 no tiene permiso para invocar la función.", "La configuración de cifrado del bucket no tiene nada que ver con el permiso de S3 para invocar una función Lambda."]],
  "dva46": ["Un usuario tiene una política IAM que permite s3:* sobre un bucket, y la bucket policy deniega explícitamente s3:DeleteObject para ese usuario. ¿Qué pasa cuando el usuario intenta eliminar un objeto?", ["La solicitud se deniega, porque un deny explícito prevalece sobre cualquier allow", "La solicitud tiene éxito, porque la política de identidad permite s3:*", "La solicitud tiene éxito solo si el objeto no está cifrado", "El resultado depende de qué política se creó más recientemente"], "En la evaluación de políticas IAM, un deny explícito en cualquier lugar prevalece sobre cualquier allow. El orden de creación es irrelevante.", [null, "Un allow nunca prevalece sobre un deny explícito; el allow de s3:* queda anulado para DeleteObject por el deny de la bucket policy.", "El estado de cifrado no afecta esta evaluación; el deny explícito se aplica a toda llamada DeleteObject de ese usuario.", "La evaluación de políticas no depende del orden de creación; todas las políticas aplicables se evalúan juntas y el deny explícito prevalece."]],
  "dva47": ["Después de iniciar sesión en un user pool de Cognito, ¿qué token contiene claims sobre el usuario, como email y nombre, para que la app los muestre?", ["El access token", "El refresh token", "El session token de STS", "El ID token"], "El ID token lleva claims de identidad sobre el usuario. El access token lleva scopes y grupos para autorizar llamadas a APIs, y el refresh token sirve para obtener tokens nuevos.", ["El access token lleva scopes y grupos para autorizar llamadas a APIs, no los claims de perfil pensados para mostrarse.", "El refresh token es opaco y solo se usa para obtener nuevos ID tokens y access tokens.", "Un session token de STS pertenece a credenciales temporales de AWS (por ejemplo, de un identity pool) y no contiene claims de perfil del usuario.", null]],
  "dva48": ["Una función Lambda en la cuenta A debe descifrar datos con una customer managed key de KMS en la cuenta B. ¿Qué permisos se necesitan?", ["Solo una política IAM en la cuenta A que permita kms:Decrypt sobre la key", "Solo una key policy en la cuenta B que nombre a la cuenta A como principal", "Una key policy en B que otorgue acceso a la cuenta A, y una política IAM en A", "Una réplica multi-Region de la key creada directamente en la cuenta A"], "El acceso a KMS entre cuentas necesita ambos lados: la key policy otorga acceso a la otra cuenta, y una política IAM en esa cuenta otorga acceso al principal. Ninguna de las dos es suficiente por sí sola.", ["Sin la key policy en la cuenta B que permita a la cuenta A, la política IAM por sí sola no puede otorgar acceso a una key de otra cuenta.", "La key policy permite que la cuenta A delegue el acceso, pero el rol de la función en la cuenta A sigue necesitando una política IAM que permita kms:Decrypt.", null, "Las réplicas multi-Region se crean en otras regiones de la misma cuenta, no en una cuenta distinta."]],
  "dva49": ["Los datos deben cifrarse dentro de la aplicación antes de enviarse a cualquier servicio de AWS, para que AWS nunca vea el texto plano. ¿Qué debe usar el desarrollador?", ["Cifrado del lado del cliente con el AWS Encryption SDK", "Cifrado predeterminado SSE-S3 configurado en cada bucket", "Cifrado del lado del servidor SSE-KMS con una AWS managed key", "TLS 1.2 o superior obligatorio en cada conexión a los servicios"], "El cifrado del lado del cliente cifra los datos antes de que salgan de la aplicación. Las opciones del lado del servidor cifran después de que el servicio recibe los datos, y TLS protege los datos solo en tránsito.", [null, "SSE-S3 cifra solo después de que S3 recibe los datos, así que AWS sigue viendo el texto plano que llega al servicio.", "SSE-KMS sigue siendo cifrado del lado del servidor; S3 recibe el texto plano y lo cifra al llegar.", "TLS protege los datos solo en tránsito; el servicio los descifra al llegar y ve el texto plano."]],
  "dva50": ["Los logs de la aplicación en CloudWatch Logs a veces contienen direcciones de email de clientes. El equipo quiere que esos valores se enmascaren automáticamente. ¿Qué deben usar?", ["Un metric filter de CloudWatch", "Un periodo de retención de logs más corto", "Un subscription filter hacia Kinesis", "Una data protection policy de CloudWatch Logs"], "Las data protection policies detectan y enmascaran datos sensibles, como direcciones de email, en los eventos de log. Los metric filters solo cuentan patrones, y una retención más corta no oculta los datos.", ["Un metric filter cuenta o extrae valores hacia métricas; no enmascara las direcciones de email en los eventos de log.", "Una retención más corta elimina los logs antes, pero los emails siguen visibles hasta entonces.", "Un subscription filter transmite los eventos de log a otro destino, copiando los datos sensibles en lugar de enmascararlos.", null]],
  "dva51": ["Un desarrollador quiere reemplazar una política amplia de un rol por otra que otorgue solo las acciones que la aplicación realmente usó en los últimos 90 días. ¿Qué herramienta ayuda a generarla?", ["Las verificaciones de optimización de costos de AWS Trusted Advisor", "La generación de políticas de IAM Access Analyzer", "Los hallazgos de vulnerabilidades de Amazon Inspector para el rol", "Conformance packs de AWS Config aplicados a la cuenta"], "IAM Access Analyzer puede revisar los logs de CloudTrail de un rol y generar una política con solo las acciones usadas. Inspector analiza las cargas de trabajo en busca de vulnerabilidades, no de permisos.", ["Las verificaciones de costos de Trusted Advisor buscan recursos inactivos o poco usados, no permisos IAM sin usar.", null, "Inspector analiza EC2, imágenes de ECR y Lambda en busca de vulnerabilidades; no genera políticas IAM.", "Los conformance packs de Config evalúan la configuración de los recursos contra reglas; no construyen una política a partir del uso real de las APIs."]],
  "dva52": ["Un desarrollador tiene una plantilla de AWS SAM y quiere compilar el código y desplegarlo por primera vez, respondiendo preguntas sobre el nombre del stack y la región. ¿Qué comandos debe ejecutar?", ["sam init y luego sam local invoke", "cdk synth y luego cdk deploy", "sam build y luego sam deploy --guided", "aws s3 cp y luego aws lambda invoke"], "sam build prepara los artefactos y sam deploy --guided pide la configuración y la guarda en samconfig.toml para ejecuciones posteriores. sam local invoke solo ejecuta una función localmente.", ["sam init crea un proyecto nuevo a partir de una plantilla y sam local invoke ejecuta una función localmente; ninguno despliega en AWS.", "cdk synth y cdk deploy pertenecen a AWS CDK, no a una plantilla de SAM existente.", null, "Copiar archivos a S3 e invocar una función no compila ni despliega el stack de SAM en absoluto."]],
  "dva53": ["Un desarrollador quiere ejecutar una función Lambda localmente con un evento de ejemplo antes de desplegarla. ¿Qué herramienta lo permite?", ["aws lambda invoke contra la versión $LATEST", "Change sets de CloudFormation", "sam local invoke con un archivo de evento (usando Docker)", "Despliegue in-place de CodeDeploy"], "SAM CLI emula el runtime de Lambda en un contenedor Docker, así que la función se puede probar localmente con un evento JSON. aws lambda invoke llama a la función desplegada en AWS.", ["aws lambda invoke llama a la función ya desplegada en AWS, así que no puede probar el código antes de desplegarlo.", "Los change sets muestran una vista previa de los cambios en los recursos de CloudFormation; no ejecutan el código de la función.", null, "CodeDeploy despliega código en destinos de cómputo de AWS; no ejecuta una función localmente para probarla."]],
  "dva54": ["Una plantilla de CloudFormation hace referencia a carpetas locales con código de Lambda. Antes de desplegar con AWS CLI, ¿qué debe pasar con ese código?", ["Pegar el código en línea en la propiedad ZipFile de cada recurso de función", "Ejecutar aws cloudformation package para subirlo a S3 y reescribir las rutas", "Guardar el código en Parameter Store y referenciar cada parámetro por nombre", "Copiar el código a una instancia EC2 desde la que CloudFormation lo lea"], "El comando package comprime los artefactos locales, los sube a un bucket de S3 y genera una plantilla con las ubicaciones en S3 para que deploy la use.", ["El código en línea con ZipFile solo sirve para funciones pequeñas de un solo archivo (hasta 4 KB) y no es la forma de empaquetar carpetas de código locales.", null, "Parameter Store guarda valores de configuración, no paquetes de despliegue, y CloudFormation no puede cargar código de funciones desde ahí.", "CloudFormation no puede leer código desde una instancia EC2; el código de la función debe venir de S3, de una imagen en ECR o en línea."]],
  "dva55": ["Un equipo despliega una nueva versión de Lambda y quiere que el 10% del tráfico vaya a ella durante 5 minutos y luego todo el tráfico si no se dispara ninguna alarma, con rollback automático. ¿Qué deben usar?", ["CodeDeploy con Canary10Percent5Minutes sobre un alias", "Una actualización all-at-once de la versión $LATEST de la función", "Dos funciones separadas detrás de un ALB con pesos de destino iguales", "Una nueva Lambda layer que contenga el código nuevo de la función"], "CodeDeploy cambia los pesos del alias entre versiones según la configuración canary y hace rollback si se disparan alarmas de CloudWatch. Actualizar $LATEST cambia todo el tráfico de una vez.", [null, "Actualizar $LATEST envía el 100% del tráfico al código nuevo de una vez, sin periodo canary ni rollback automático.", "Los destinos ponderados de un ALB podrían dividir el tráfico, pero no hay un paso canary automático de 5 minutos ni rollback basado en alarmas.", "Una layer contiene bibliotecas compartidas; no controla el tráfico entre versiones ni hace rollback."]],
  "dva56": ["¿Qué opción de cambio de tráfico de CodeDeploy para Lambda mueve el tráfico en incrementos iguales a intervalos fijos, por ejemplo 10% cada minuto?", ["Canary", "All-at-once", "Blue/green con intercambio de CNAME", "Linear"], "Linear mueve porcentajes iguales a intervalos regulares hasta llegar al 100%. Canary mueve primero un porcentaje, espera y luego mueve el resto.", ["Canary mueve un porcentaje inicial, espera y luego mueve todo el tráfico restante de una vez, en lugar de hacerlo en pasos iguales.", "All-at-once mueve el 100% del tráfico de inmediato, sin incrementos.", "Un intercambio de CNAME es una técnica blue/green de Elastic Beanstalk, no una configuración de cambio de tráfico de CodeDeploy para Lambda.", null]],
  "dva57": ["Una app de producción en Elastic Beanstalk debe mantener su capacidad completa durante los despliegues, y un despliegue fallido debe revertirse rápidamente terminando las instancias nuevas. ¿Qué política de despliegue es la adecuada?", ["All at once", "Immutable", "Rolling", "Rolling with an additional batch"], "Los despliegues immutable lanzan instancias nuevas en un Auto Scaling group temporal, así que las anteriores siguen atendiendo; el rollback solo termina el grupo nuevo. Rolling reduce la capacidad durante la actualización.", ["All at once saca de servicio todas las instancias a la vez, lo que causa tiempo de inactividad y un redespliegue lento para revertir.", null, "Rolling actualiza las instancias por lotes, así que la capacidad baja durante el despliegue y revertir significa volver a desplegar.", "Rolling with an additional batch mantiene la capacidad, pero actualiza las instancias existentes, así que revertir requiere otro despliegue en lugar de terminar instancias nuevas."]],
  "dva58": ["Un desarrollador quiere el despliegue de Elastic Beanstalk más rápido posible para un entorno de desarrollo y puede aceptar una breve inactividad. ¿Qué política debe usar?", ["Immutable", "Traffic splitting", "All at once", "Rolling with an additional batch"], "All at once actualiza todas las instancias al mismo tiempo, lo cual es lo más rápido, pero causa una interrupción mientras las instancias se reinician.", ["Immutable lanza un conjunto completamente nuevo de instancias, lo cual es seguro pero es la política más lenta.", "Traffic splitting ejecuta instancias nuevas junto a las anteriores durante un periodo de evaluación, lo que tarda más.", null, "Rolling with an additional batch lanza instancias extra y actualiza por lotes, lo cual es más lento que all at once."]],
  "dva59": ["Un equipo ejecuta la versión 2 en un entorno separado de Elastic Beanstalk y quiere hacer el cambio casi sin inactividad y con una forma fácil de volver atrás. ¿Qué debe hacer?", ["Intercambiar las URL de los entornos (CNAME swap) entre los dos entornos", "Desplegar la versión 2 en el entorno existente con la política all-at-once", "Eliminar el entorno anterior y luego renombrar el nuevo", "Cambiar el tamaño mínimo del Auto Scaling group a cero"], "Un intercambio blue/green intercambia los CNAME para que el tráfico pase al entorno nuevo; volver a intercambiarlos restaura el anterior.", [null, "Un despliegue all-at-once en el entorno existente causa inactividad y no tiene una forma rápida de volver atrás.", "Eliminar el entorno anterior quita la vía fácil de rollback, y los entornos no se pueden simplemente renombrar para tomar la URL.", "Poner el tamaño mínimo en cero podría apagar la capacidad; no mueve el tráfico a la versión 2."]],
  "dva60": ["Un pipeline de CodePipeline debe pausarse después de desplegar en staging hasta que un líder de equipo confirme el release. ¿Qué se debe agregar?", ["Una acción de prueba de CodeBuild que se ejecute automáticamente después del despliegue en staging", "Una alarma de CloudWatch que detenga el pipeline hasta que se despeje", "Un timeout más largo en la acción de despliegue en staging del pipeline", "Una acción de aprobación manual entre las etapas de staging y producción"], "Las acciones de aprobación manual detienen el pipeline hasta que alguien aprueba o rechaza, y opcionalmente envían una notificación de SNS.", ["Una acción de prueba automatizada se ejecuta sin una persona; no puede esperar la confirmación de un líder de equipo.", "Las alarmas de CloudWatch no pausan un pipeline para que una persona dé su visto bueno; la acción de aprobación manual es la forma integrada de hacerlo.", "Un timeout de acción más largo solo permite que el despliegue dure más; no pausa el pipeline para que alguien apruebe.", null]],
  "dva61": ["En un buildspec.yml de CodeBuild, ¿dónde deben ubicarse las pruebas unitarias que deben ejecutarse después de compilar el código?", ["En la sección runtime-versions de la fase install", "En los commands de la fase build o post_build", "En la sección files de artifacts", "En la sección variables de env"], "Las fases se ejecutan en orden: install, pre_build, build, post_build. Las pruebas posteriores a la compilación van en build o post_build; artifacts solo enumera los archivos de salida.", ["runtime-versions selecciona los runtimes del lenguaje durante install, que ocurre antes de compilar el código.", null, "La sección artifacts enumera los archivos de salida que se conservan; no ejecuta comandos.", "La sección env define variables de entorno y no ejecuta comandos."]],
  "dva62": ["Un despliegue de CodeDeploy en EC2 debe ejecutar pruebas de integración después de que la aplicación haya iniciado. ¿Qué hook de appspec.yml debe ejecutar el script de pruebas?", ["ValidateService", "BeforeInstall", "ApplicationStop", "DownloadBundle"], "ValidateService es el último hook de un despliegue EC2/on-premises y se ejecuta después de ApplicationStart, así que es el lugar para verificar el servicio. DownloadBundle está reservado para el agente y no puede ejecutar scripts.", [null, "BeforeInstall se ejecuta antes de instalar los archivos nuevos, así que la aplicación todavía no está corriendo.", "ApplicationStop se ejecuta primero, para detener la versión anterior, mucho antes de que inicie la aplicación nueva.", "DownloadBundle lo ejecuta el propio agente de CodeDeploy y no puede ejecutar scripts de usuario."]],
  "dva63": ["Un despliegue de CodeDeploy en un nuevo conjunto de instancias EC2 falla de inmediato sin registrar ningún lifecycle event. ¿Cuál es la causa MÁS probable?", ["El bundle de la revisión está guardado en S3 en lugar de en un repositorio de GitHub", "El agente de CodeDeploy no está instalado o no se está ejecutando en las instancias", "El deployment group selecciona las instancias por tag de EC2 en lugar de por ASG", "El archivo appspec.yml no define un lifecycle hook ValidateService"], "En EC2, el agente de CodeDeploy es quien ejecuta los despliegues; sin él no se ejecuta ningún lifecycle event. Los bundles en S3 y los grupos basados en tags son normales.", ["Guardar la revisión en S3 es un origen normal y admitido por CodeDeploy, y no impide que se ejecuten los lifecycle events.", null, "Los deployment groups basados en tags son una forma normal de apuntar a instancias EC2 y no impiden los lifecycle events.", "ValidateService es opcional; omitirlo no impediría que se ejecuten todos los lifecycle events."]],
  "dva64": ["Una API de API Gateway tiene los stages dev y prod, y cada stage debe llamar a un alias distinto de la misma función Lambda. ¿Qué debe usar el desarrollador?", ["Una cuenta de AWS separada para cada stage", "Dos funciones Lambda distintas con código idéntico", "Stage variables referenciadas en el ARN de la integración Lambda", "Usage plans asociados a cada stage"], "La integración puede hacer referencia a ${stageVariables.alias}, así que cada stage llama a su propio alias. Recuerda permitir que API Gateway invoque cada alias.", ["Tener cuentas separadas por stage igual obligaría a que cada stage tenga su propio destino de integración; las stage variables lo resuelven dentro de una sola API.", "Duplicar funciones genera divergencia de código e ignora los alias, que existen para apuntar a versiones de una misma función.", null, "Los usage plans aplican throttling y miden las API keys por stage; no pueden cambiar a qué alias de Lambda llama la integración."]],
  "dva65": ["Un desarrollador cambió varios métodos de una REST API en la consola de API Gateway, pero los clientes siguen viendo el comportamiento anterior. ¿Qué paso se omitió?", ["Habilitar CORS en la API", "Crear un nuevo usage plan", "Desplegar la API en el stage", "Activar la caché del stage"], "Los cambios en una REST API solo entran en vigor después de un despliegue en un stage, que crea una nueva instantánea.", ["CORS controla qué orígenes del navegador pueden llamar a la API; no publica los métodos modificados.", "Los usage plans administran el throttling y las cuotas de las API keys; no activan los cambios en los métodos.", null, "La caché del stage podría servir respuestas anteriores, pero está desactivada de forma predeterminada; el paso que falta es desplegar los cambios en el stage."]],
  "dva66": ["Las dependencias de una función Lambda suman 1.5 GB, lo que es demasiado para un paquete de despliegue .zip. ¿Cómo puede ejecutarse igualmente en Lambda?", ["Empaquetarla como una imagen de contenedor en Amazon ECR", "Repartir las dependencias en seis Lambda layers", "Subir el .zip a S3 en lugar de hacerlo directamente", "Guardar las bibliotecas en variables de entorno"], "Se admiten imágenes de contenedor de hasta 10 GB. Los paquetes .zip, incluidas las layers, están limitados a 250 MB descomprimidos, así que agregar layers no ayuda.", [null, "Las layers cuentan para el mismo límite de 250 MB descomprimidos que el paquete de la función, así que repartir entre layers no ayuda.", "Subir mediante S3 aumenta el límite de tamaño de carga, pero el límite de 250 MB descomprimidos sigue aplicando.", "Las variables de entorno están limitadas a 4 KB en total y no pueden contener bibliotecas."]],
  "dva67": ["Antes de actualizar un stack de CloudFormation de producción, un desarrollador quiere ver exactamente qué recursos se modificarán o reemplazarán. ¿Qué debe usar?", ["Detección de drift del stack", "Una stack policy", "Termination protection", "Un change set"], "Un change set enumera los cambios propuestos, incluidos los reemplazos, antes de ejecutarlo. La detección de drift, en cambio, compara los recursos actuales con la última plantilla desplegada.", ["La detección de drift compara los recursos en vivo con la última plantilla desplegada; no muestra una vista previa de una nueva actualización.", "Una stack policy protege recursos para que no se actualicen o reemplacen, pero no muestra lo que hará un cambio.", "Termination protection solo impide que se elimine el stack.", null]],
  "dva68": ["Un stack de red crea una VPC, y los stacks de aplicación deben hacer referencia a sus IDs de subred sin escribirlos directamente. ¿Qué debe usar el desarrollador?", ["Fn::GetAtt con el nombre del stack de red para leer sus subredes", "IDs de subred copiados a mano en los Mappings de cada plantilla de aplicación", "Outputs exportados por el stack de red, leídos con Fn::ImportValue", "Un atributo DependsOn que apunte al stack de red"], "Las referencias entre stacks exportan un output de un stack y lo importan por nombre en otro. Fn::GetAtt solo funciona dentro de una misma plantilla.", ["Fn::GetAtt solo lee atributos de recursos de la misma plantilla; no puede acceder a otro stack.", "Copiar los IDs en Mappings es escribirlos directamente, y las plantillas se rompen cada vez que cambia el stack de red.", null, "DependsOn solo ordena la creación de recursos dentro de una plantilla; no puede hacer referencia a otro stack ni pasar valores."]],
  "dva69": ["Un equipo define su infraestructura en TypeScript con AWS CDK. ¿Qué comando produce la plantilla de CloudFormation sin desplegarla?", ["cdk bootstrap", "cdk deploy", "cdk destroy", "cdk synth"], "cdk synth sintetiza la app en plantillas de CloudFormation. cdk bootstrap crea los recursos que CDK necesita en una cuenta y región.", ["cdk bootstrap aprovisiona los recursos de staging (como un bucket de S3 y roles) que CDK necesita en una cuenta y región.", "cdk deploy sintetiza y luego despliega los stacks, que es lo que la pregunta quiere evitar.", "cdk destroy elimina los stacks desplegados.", null]],
  "dva70": ["Un equipo de front-end necesita un endpoint de API que devuelva una respuesta JSON de ejemplo fija para poder construir la interfaz antes de que exista el backend. ¿Cuál es la opción más rápida?", ["Una función Lambda con provisioned concurrency", "Un Application Load Balancer con destinos fijos", "Una mock integration de API Gateway", "Una tabla de DynamoDB con un ítem de ejemplo"], "Las mock integrations devuelven una respuesta definida en API Gateway sin llamar a ningún backend, lo que sirve para pruebas tempranas.", ["Una función Lambda igual hay que escribirla y desplegarla, y provisioned concurrency solo reduce los cold starts con un costo extra.", "Una regla de respuesta fija de un ALB puede devolver texto estático, pero agrega un balanceador que se cobra por hora y es más lenta de configurar que una mock integration en la propia API.", null, "Una tabla de DynamoDB es solo almacenamiento; seguirías necesitando una API y código para devolver el ítem."]],
  "dva71": ["Un equipo quiere aplicar un cambio de configuración a su aplicación de forma gradual, validarlo contra un esquema y revertirlo automáticamente si se dispara una alarma, sin volver a desplegar código. ¿Qué debe usar?", ["Una nueva versión de Lambda por cada cambio de configuración", "AWS AppConfig con una estrategia de despliegue y validadores", "Variables de entorno actualizadas con la CLI", "Una stack policy de CloudFormation"], "AppConfig despliega configuración y feature flags con estrategias graduales, validadores y rollback basado en alarmas de CloudWatch. Cambiar variables de entorno vuelve a desplegar la configuración de la función de una sola vez.", ["Publicar una nueva versión por cada cambio de configuración es un despliegue de código, sin validación de esquema ni aplicación gradual de la configuración.", null, "Actualizar variables de entorno cambia la configuración para todas las invocaciones a la vez, sin validador ni rollback por alarma.", "Una stack policy impide actualizaciones a los recursos protegidos; no aplica configuración de forma gradual."]],
  "dva72": ["Varios equipos quieren alojar paquetes privados de npm y PyPI y hacer de proxy de los registros públicos para sus builds. ¿Qué servicio es el adecuado?", ["AWS CodeArtifact", "Amazon ECR", "AWS CodeDeploy", "Amazon S3 Glacier"], "CodeArtifact es un repositorio de artefactos administrado para npm, PyPI, Maven y más, con conexiones upstream a los registros públicos. ECR guarda imágenes de contenedor.", [null, "ECR guarda imágenes de contenedor, no paquetes de npm o PyPI, y no hace de proxy de esos registros públicos.", "CodeDeploy despliega aplicaciones en destinos de cómputo; no es un repositorio de paquetes.", "S3 Glacier es almacenamiento de archivo con recuperación lenta y sin soporte para protocolos de gestores de paquetes."]],
  "dva73": ["Un desarrollador usa X-Ray y quiere filtrar las trazas por nivel de cliente (por ejemplo, tier = gold). ¿Dónde debe registrarse ese valor?", ["Como metadata en el segmento", "En las variables de entorno de la función", "Como annotation en el segmento o subsegmento", "En el header del trace ID"], "Las annotations son pares clave-valor indexados que puedes usar en filter expressions. La metadata se guarda con la traza, pero no se indexa para búsquedas.", ["La metadata se guarda con la traza pero no se indexa, así que las filter expressions no pueden buscar en ella.", "Las variables de entorno configuran la función y no se registran en las trazas, así que X-Ray no puede filtrar por ellas.", null, "El header del trace ID solo propaga el contexto de la traza entre servicios; no puedes agregar valores personalizados para filtrar."]],
  "dva74": ["Una aplicación en EC2 está instrumentada con el X-Ray SDK, pero no aparece ninguna traza en X-Ray. ¿Cuál es la causa MÁS probable?", ["El daemon o agente de X-Ray no se está ejecutando, o el rol no puede escribir trazas", "El active tracing no está activado para la instancia en la consola de Lambda", "La instancia no tiene una Elastic IP, así que las trazas no pueden salir", "CloudTrail está deshabilitado en la región, así que no se recopilan datos de trazas"], "En EC2, el SDK envía los segmentos por UDP a un daemon o agente local, que los sube usando el rol de la instancia. La configuración de active tracing de Lambda no aplica a EC2.", [null, "El active tracing es una configuración de Lambda; no aplica a una instancia EC2.", "Las trazas llegan a X-Ray a través del daemon o agente usando la conectividad saliente normal; no se requiere una Elastic IP.", "CloudTrail registra la actividad de las APIs y no tiene relación con la recopilación de segmentos de trazas de X-Ray."]],
  "dva75": ["Una función Lambda debe publicar métricas de negocio personalizadas en CloudWatch sin hacer llamadas síncronas a PutMetricData en cada solicitud. ¿Qué debe usar?", ["Una suscripción de CloudWatch Logs hacia Kinesis", "El embedded metric format de CloudWatch en su salida de logs", "Una sampling rule de X-Ray", "Data events de CloudTrail"], "El embedded metric format escribe líneas de log JSON estructuradas que CloudWatch convierte en métricas de forma asíncrona, evitando llamadas extra a la API y latencia.", ["Un subscription filter transmite los eventos de log a Kinesis; no crea métricas de CloudWatch a partir de ellos.", null, "Las sampling rules deciden qué solicitudes traza X-Ray; no publican métricas de negocio.", "Los data events de CloudTrail registran llamadas a APIs para auditoría y no producen métricas personalizadas de la aplicación."]],
  "dva76": ["Durante un incidente, un desarrollador necesita encontrar las 20 solicitudes más lentas de la última hora en muchos log streams. ¿Qué herramienta es la MÁS adecuada?", ["AWS Config", "Amazon Inspector", "IAM Access Analyzer", "CloudWatch Logs Insights"], "Logs Insights ejecuta consultas (filter, stats, sort) sobre log groups, lo que sirve para encontrar las solicitudes más lentas. Las otras herramientas son para configuración, vulnerabilidades y permisos.", ["AWS Config registra los cambios de configuración de los recursos, no los logs de solicitudes de la aplicación.", "Inspector analiza las cargas de trabajo en busca de vulnerabilidades de software y no puede consultar eventos de log.", "Access Analyzer encuentra accesos no deseados a recursos y genera políticas; no busca en logs.", null]],
  "dva77": ["Durante un pico de tráfico, las llamadas síncronas a una función Lambda fallan con TooManyRequestsException (HTTP 429). ¿Cuál es la causa MÁS probable?", ["La memoria de la función está configurada demasiado alta", "El paquete de despliegue pesa más de 50 MB", "La función alcanzó su límite de concurrencia", "Al execution role de la función le falta una política"], "El throttling 429 significa que no hay concurrencia disponible, ya sea por el límite de la cuenta o por la concurrencia reservada de la función. Solicita un aumento de cuota o ajusta la concurrencia reservada; una política faltante causaría AccessDenied.", ["Más memoria aumenta el costo por milisegundo, pero no causa errores de throttling 429.", "Un paquete demasiado grande falla al momento del despliegue, no con throttling en tiempo de ejecución durante un pico de tráfico.", null, "Una política faltante en el execution role causa errores AccessDenied del servicio llamado, no un 429 de Lambda."]],
  "dva78": ["Una función Lambda con uso intensivo de CPU tarda 9 segundos con 512 MB de memoria. ¿Qué cambio es el MÁS probable que la haga más rápida?", ["Aumentar la configuración de memoria, que también asigna más CPU", "Aumentar el timeout para que la función tenga más tiempo para terminar", "Agregar concurrencia reservada para que cada invocación tenga un núcleo dedicado", "Mover el código de la función a una layer para que cargue más rápido"], "Lambda asigna CPU en proporción a la memoria, así que más memoria suele acortar las ejecuciones limitadas por CPU e incluso puede reducir el costo. Un timeout más largo no agrega velocidad.", [null, "Un timeout más largo solo permite que la función se ejecute más tiempo; no hace más rápido el trabajo limitado por CPU.", "La concurrencia reservada limita y garantiza el número de entornos concurrentes; no agrega CPU a cada uno.", "Las layers solo empaquetan código compartido; el código se ejecuta igual y no recibe CPU extra."]],
  "dva79": ["Una API sensible a la latencia respaldada por Lambda tiene respuestas lentas después de periodos sin tráfico porque deben iniciarse nuevos entornos de ejecución. ¿Qué elimina la mayor parte de este retraso?", ["Provisioned concurrency en el alias de la función", "Una configuración de almacenamiento /tmp más grande", "Concurrencia reservada configurada en 0", "Una dead-letter queue"], "Provisioned concurrency mantiene entornos inicializados listos, lo que evita los cold starts. Una concurrencia reservada de 0 impediría que la función se ejecute. Provisioned concurrency se cobra mientras está configurada.", [null, "El tamaño del almacenamiento efímero /tmp no afecta cuánto tarda en inicializarse un nuevo entorno de ejecución.", "Una concurrencia reservada de 0 aplica throttling a todas las invocaciones, así que la función no se ejecutaría en absoluto.", "Una DLQ captura los eventos asíncronos fallidos; no hace nada respecto de la latencia de los cold starts."]],
  "dva80": ["Una tabla de DynamoDB que usa la fecha como partition key aplica throttling a las escrituras aunque la capacidad total consumida está muy por debajo del límite de la tabla. ¿Cuál es la causa probable y la solución?", ["La tabla necesita un local secondary index sobre el atributo de fecha", "Una partición caliente; usar una partition key con muchos valores distintos", "Las lecturas fuertemente consistentes están habilitadas en los Query de la tabla", "Falta el atributo TTL, así que los ítems viejos nunca se eliminan"], "Todas las escrituras del día caen en un mismo valor de partition key, lo que concentra el tráfico. Una clave de alta cardinalidad (o agregar un sufijo aleatorio) reparte las escrituras entre particiones.", ["Un LSI debe definirse al crear la tabla, comparte la misma partition key y agrega carga de escritura en lugar de repartirla.", null, "Las lecturas fuertemente consistentes afectan la capacidad de lectura, no el throttling de escrituras sobre un valor de partition key.", "TTL elimina los ítems expirados, pero no reparte las escrituras del día entre particiones."]],
  "dva81": ["Una REST API devuelve el mismo catálogo de productos a miles de clientes, y cada solicitud invoca Lambda y lee DynamoDB. ¿Cómo puede el desarrollador reducir las llamadas al backend con el mínimo código?", ["Aumentar la memoria de la función Lambda", "Cambiar DynamoDB a capacidad on-demand", "Agregar una dead-letter queue a la función", "Habilitar la caché del stage de API Gateway con un TTL adecuado"], "La caché del stage devuelve respuestas en caché durante el TTL sin invocar el backend. Ten en cuenta que la caché se cobra por hora y no forma parte del Free Tier.", ["Más memoria hace más rápida cada invocación, pero cada solicitud sigue invocando Lambda y leyendo DynamoDB.", "La capacidad on-demand cambia cómo se cobra y escala DynamoDB, pero no reduce el número de llamadas al backend.", "Una DLQ captura los eventos asíncronos fallidos y no reduce las solicitudes del mismo catálogo.", null]],
  "dva82": ["Usuarios de todo el mundo descargan imágenes estáticas desde un bucket de S3 y experimentan latencia alta. ¿Cuál es la MEJOR mejora?", ["Habilitar el versionado de S3", "Servir el bucket a través de una distribución de CloudFront", "Mover las imágenes a DynamoDB", "Habilitar S3 Object Lock"], "CloudFront guarda en caché el contenido en edge locations cercanas a los usuarios. El versionado y Object Lock protegen los datos, pero no reducen la latencia.", ["El versionado conserva versiones anteriores de los objetos para recuperarlas; no hace nada por la latencia de descarga.", null, "DynamoDB tiene un límite de 400 KB por ítem y no es adecuado para servir imágenes, ni estaría más cerca de los usuarios.", "Object Lock aplica retención WORM; no guarda contenido en caché cerca de los usuarios."]],
  "dva83": ["Un mensaje mal formado en una cola SQS sigue fallando y reintentándose, lo que quita atención a otro trabajo. ¿Cómo debe el desarrollador aislar ese tipo de mensajes?", ["Configurar una dead-letter queue con un maxReceiveCount", "Reducir el periodo de retención de mensajes de la cola a 1 minuto", "Desactivar el long polling para que los consumidores consulten con más frecuencia", "Aumentar el tamaño de lote a 10 para que los mensajes malos se diluyan"], "Una redrive policy mueve un mensaje a la DLQ después de que se ha recibido maxReceiveCount veces, para poder inspeccionarlo sin reintentos interminables.", [null, "Una retención de 1 minuto eliminaría todos los mensajes lentos o sin procesar, no solo el mal formado.", "Desactivar el long polling solo aumenta las recepciones vacías y el costo; el mensaje malo sigue fallando.", "Un lote más grande no aísla el mensaje malo y puede hacer que se reintenten más mensajes buenos junto con él."]],
  "dva84": ["Una función Lambda que lee un Kinesis data stream muestra una métrica IteratorAge que sube de forma constante. ¿Qué indica esto y qué ayuda?", ["Los registros están expirando antes de tiempo; reducir el periodo de retención", "La función está sobreaprovisionada; reducir su memoria", "La función se está quedando atrás; aumentar el parallelization factor o agregar shards", "El stream está vacío; agregar un productor"], "Un iterator age creciente significa que los registros esperan más tiempo antes de procesarse. Procesar más lotes en paralelo por shard, agregar shards o acelerar el código lo reduce.", ["Los registros expiran solo después del periodo de retención, y un periodo más corto haría que los registros atrasados expiren y se pierdan.", "Reducir la memoria haría más lenta la función y aumentaría aún más el retraso.", null, "Un stream vacío no produciría crecimiento del iterator age; un valor creciente significa que hay registros esperando sin procesar."]],
  "dva85": ["Un desarrollador quiere recibir un email cuando el conteo de errores de una función supere 5 en 5 minutos. ¿Qué debe configurar?", ["Una alarma de CloudWatch sobre la métrica Errors que notifique a un tema SNS de email", "Un trail de CloudTrail que envíe un email por cada llamada a la API de Lambda", "Un grupo de X-Ray con una filter expression que coincida con las trazas fallidas", "Un destino de Lambda que se dispare en cada invocación exitosa"], "Las alarmas de CloudWatch vigilan una métrica contra un umbral y pueden enviar notificaciones a través de SNS.", [null, "CloudTrail registra llamadas a la API de Lambda, como las actualizaciones de funciones, no los errores de invocación, y enviar un email por cada llamada no es una alerta por umbral.", "Un grupo de X-Ray filtra trazas, pero por sí solo no envía un email cuando los errores superan un umbral en 5 minutos.", "Un destino para invocaciones exitosas se dispara con los éxitos, no con un umbral de conteo de errores."]],
  "dva86": ["Las solicitudes pasan por API Gateway, dos funciones Lambda y SQS. Cuando un usuario reporta un error, los ingenieros no pueden relacionar las líneas de log de cada componente. ¿Qué práctica de logging ayuda MÁS?", ["Configuraciones de retención de logs más largas en el log group de cada componente", "Logs JSON estructurados que lleven un ID de correlación para cada solicitud", "Escribir los logs de cada componente en su carpeta local /tmp", "Registrar solo los errores y descartar todos los mensajes informativos"], "Un ID de correlación (o de traza) compartido en logs estructurados permite buscar una solicitud en todos los componentes, por ejemplo con Logs Insights.", ["Una retención más larga conserva los logs más tiempo, pero no vincula las líneas de log de distintos componentes con una solicitud.", null, "/tmp es almacenamiento efímero local de un entorno de ejecución, así que los logs ahí se pierden y no se pueden buscar.", "Descartar los logs informativos elimina contexto y sigue sin ofrecer una forma de unir los eventos de una solicitud."]],
  "dva87": ["Una REST API de API Gateway llama a una función Lambda que a veces necesita 2 minutos para generar un reporte, y los clientes reciben errores 504. ¿Cuál es el MEJOR cambio de diseño?", ["Subir el timeout de Lambda a 15 minutos", "Aumentar la memoria de Lambda al máximo", "Devolver de inmediato un ID de trabajo y procesar el reporte de forma asíncrona", "Habilitar la caché en el stage de la API"], "Las integraciones de REST API expiran a los 29 segundos de forma predeterminada, así que el 504 ocurre sin importar cuánto pueda ejecutarse Lambda. Un patrón de trabajo asíncrono evita mantener abierta la solicitud.", ["Lambda puede ejecutarse durante 15 minutos, pero la integración de API Gateway sigue expirando a los 29 segundos de forma predeterminada y devuelve 504.", "Más memoria puede acelerar el reporte, pero es poco probable que un trabajo de 2 minutos quepa en el timeout de integración de 29 segundos.", null, "La caché devuelve respuestas guardadas para solicitudes repetidas; la primera solicitud de cada reporte sigue expirando."]],
  "dva88": ["Una función Lambda falla con AccessDeniedException al llamar a s3:GetObject sobre un bucket de la misma cuenta. El bucket no tiene política. ¿Dónde debe mirar primero el desarrollador?", ["La resource-based policy de la función", "La concurrencia reservada de la función", "La configuración CORS del bucket", "La política del execution role de la función"], "Las llamadas que hace la función se autorizan con su execution role. La resource-based policy controla quién puede invocar la función, y CORS solo afecta a los navegadores.", ["La resource-based policy controla quién puede invocar la función, no a qué puede acceder la función.", "La concurrencia reservada limita cuántas copias se ejecutan; no causa AccessDeniedException.", "CORS solo rige las solicitudes cross-origin de los navegadores; no autoriza las llamadas del SDK desde Lambda.", null]],
  "dva89": ["Una app con muchas lecturas envía las mismas consultas SQL costosas a una base de datos RDS muchas veces por segundo, y los resultados cambian rara vez. ¿Qué debe agregar el desarrollador?", ["Un volumen de almacenamiento más grande para la instancia RDS", "Una caché de Amazon ElastiCache con lazy loading y un TTL", "Un subscription filter de CloudWatch Logs", "Un segundo NAT gateway"], "Guardar en caché los resultados de las consultas en ElastiCache reduce las lecturas repetidas a la base de datos, y un TTL limita qué tan desactualizados pueden quedar los resultados.", ["Más almacenamiento agrega capacidad para datos, pero no reduce la carga de consultas repetidas sobre la base de datos.", null, "Un subscription filter transmite logs a otro destino y no tiene efecto sobre la carga de consultas a la base de datos.", "Un NAT gateway proporciona acceso saliente a internet para subredes privadas y no guarda en caché ni reduce las consultas a la base de datos."]],
  "x1": ["Un equipo debe procesar decenas de miles de eventos IoT por segundo con AWS Step Functions. Cada ejecución termina en mucho menos de un minuto, y el bajo costo por ejecución importa más que un historial de ejecución largo y exactly-once. ¿Qué tipo de workflow es el adecuado?", ["Standard workflows, porque guardan un historial de ejecución completo de cada ejecución", "Express workflows, diseñados para procesar eventos de alto volumen y corta duración", "Standard workflows con un estado Wait que primero agrupe los eventos en lotes", "Activity tasks consultadas por workers en EC2 desde dentro de un Standard workflow"], "Los Express workflows están diseñados para tasas de eventos altas y ejecuciones cortas (hasta cinco minutos) y tienen precios pensados para volumen. Los Standard workflows ofrecen ejecución exactly-once con un historial largo, que este escenario dice no necesitar.", ["Los Standard workflows sirven para orquestación exactly-once de larga duración; con esta tasa de eventos y duración corta cuestan más que Express.", null, "Un estado Wait solo pausa una ejecución; no agrupa eventos y sigue dejando cada ejecución como una ejecución Standard más cara.", "Los activity workers agregan servidores que administrar y no hacen nada respecto del costo por ejecución de un Standard workflow."]],
  "x2": ["Un estado Task de Step Functions llama a una función Lambda que a veces falla con un error transitorio. El workflow debe reintentar algunas veces con retrasos crecientes y, si sigue fallando, pasar a un estado de limpieza. ¿Qué debe agregar el desarrollador al estado Task?", ["Un estado Choice después de la tarea que vuelva atrás cuando la salida tenga un error", "Un estado Parallel que ejecute la misma tarea dos veces y conserve la rama que funcione", "Un estado Wait antes de la tarea para que el servicio de destino se recupere primero", "Un campo Retry con un BackoffRate y un campo Catch que dirija a la limpieza"], "Retry con IntervalSeconds, MaxAttempts y BackoffRate ofrece reintentos exponenciales acotados, y Catch envía cualquier falla restante a un estado de recuperación. Un bucle con Choice es la tentadora opción hecha a mano, pero no tiene backoff y no puede capturar los errores de la tarea.", ["Un bucle Choice hecho a mano reinventa Retry, no tiene backoff integrado y nunca captura los errores que detienen directamente el estado Task.", "Ejecutar la tarea dos veces en paralelo duplica los efectos secundarios y no ofrece reintentos acotados ni enrutamiento de fallas.", "Un Wait fijo antes del primer intento no reintenta nada después de una falla y agrega retraso a cada ejecución exitosa.", null]],
  "x3": ["Un script llama a Scan de DynamoDB mediante el SDK y procesa solo una parte de una tabla grande. La respuesta contiene un valor LastEvaluatedKey. ¿Qué está pasando y qué debe hacer el script?", ["Se alcanzó el límite de página de 1 MB; volver a llamar a Scan con ExclusiveStartKey", "La tabla aplicó throttling a la llamada y devolvió datos parciales en lugar de un error", "Las lecturas eventualmente consistentes ocultaron algunos ítems; reintentar con ConsistentRead", "El filtro eliminó los demás ítems; la clave marca la última coincidencia encontrada"], "Scan y Query devuelven como máximo 1 MB por llamada. LastEvaluatedKey le indica a quien llama que pida la página siguiente pasándolo como ExclusiveStartKey (o que use el paginador del SDK). El throttling se ve distinto: lanza una excepción.", [null, "El throttling devuelve una ProvisionedThroughputExceededException, no una página parcial con un LastEvaluatedKey.", "La consistencia afecta qué tan recientes son los ítems, no cuántos se devuelven; un LastEvaluatedKey significa que quedan más páginas.", "Una FilterExpression se aplica después de leer cada página; LastEvaluatedKey indica que queda más tabla por recorrer."]],
  "x4": ["Justo después de llamar a CreateTable con el SDK, un script escribe ítems y falla porque la tabla todavía se está creando. ¿Cuál es la solución más limpia?", ["Reintentar cada escritura en un bucle cerrado cada pocos milisegundos hasta que funcione", "Cambiar la tabla a capacidad on-demand para que quede activa de inmediato", "Usar el waiter del SDK para la existencia de la tabla antes de escribir ítems", "Llamar una vez a DescribeTable y empezar a escribir sea cual sea el estado que devuelva"], "Los waiters del SDK (como TableExists / table_exists) consultan DescribeTable hasta que la tabla está ACTIVE, con retrasos y un límite máximo de intentos. Un bucle cerrado hecho a mano es tentador, pero satura la API y no tiene backoff.", ["Un bucle de reintentos cerrado desperdicia llamadas y puede provocar throttling; los waiters consultan a intervalos razonables y con un límite.", "El modo de capacidad no omite la creación de la tabla; la tabla sigue pasando por CREATING antes de estar ACTIVE.", null, "Verificar una sola vez sin actuar según el estado no hace nada para esperar a ACTIVE, así que las escrituras pueden seguir fallando."]],
  "x5": ["Una instancia EC2 tiene un rol de instance profile, pero un desarrollador también exportó AWS_ACCESS_KEY_ID y AWS_SECRET_ACCESS_KEY de un usuario IAM en la shell. Las llamadas del SDK de la aplicación se ejecutan con los permisos del usuario IAM. ¿Por qué?", ["El instance profile se ignora siempre que la instancia tiene una dirección IPv4 pública", "IAM siempre prefiere los permisos del usuario IAM sobre los del rol cuando existen ambos", "La cadena de credenciales predeterminada revisa las variables de entorno antes que el rol de la instancia", "Las credenciales del rol expiraron, así que el SDK recurrió a las variables de entorno"], "La cadena de proveedores predeterminada del SDK encuentra las credenciales explícitas y las de variables de entorno antes de llegar al rol del instance metadata, así que las keys que quedaron prevalecen sobre el rol. Eliminar las variables permite usar el instance profile. Pensar que las credenciales del rol expiraron es tentador, pero el SDK las renueva.", ["Una IP pública no afecta si el SDK lee las credenciales del instance metadata.", "IAM evalúa el único principal que hace la llamada; nunca combina ni prefiere usuarios sobre roles.", null, "El SDK renueva automáticamente las credenciales del rol; las variables de entorno ganan porque aparecen antes en la cadena."]],
  "x6": ["Una función Lambda descarga un archivo de modelo de 2 GB desde S3 en cada cold start y falla con 'No space left on device'. La memoria y el timeout están bien. ¿Qué debe cambiar el desarrollador?", ["Aumentar la configuración de almacenamiento efímero (/tmp) de la función", "Subir el timeout de la función al máximo permitido de 15 minutos", "Poner el archivo del modelo en una variable de entorno", "Activar provisioned concurrency en el alias"], "El /tmp de Lambda es de 512 MB de forma predeterminada y se puede configurar más grande (hasta 10,240 MB). Un archivo más grande que el valor predeterminado necesita más almacenamiento efímero. Provisioned concurrency es tentador porque reduce los cold starts, pero no cambia el tamaño del disco.", [null, "El error es por espacio en disco, no por tiempo; un timeout más largo sigue dejando /tmp demasiado pequeño.", "Las variables de entorno están limitadas a unos pocos kilobytes en total y no pueden contener un archivo binario grande.", "Provisioned concurrency mantiene los entornos calientes, pero no amplía su almacenamiento /tmp."]],
  "x7": ["Una función Lambda invocada de forma asíncrona debe enviar un registro de cada invocación exitosa, incluida la respuesta de la función, a una función de auditoría sin cambiar el código del handler. ¿Qué se debe configurar?", ["Una dead-letter queue asociada a la función para los eventos asíncronos", "Una suscripción de CloudWatch Logs en el log group", "Concurrencia reservada en la función de auditoría", "Un destino on-success para las invocaciones asíncronas"], "Los destinos de Lambda para invocaciones asíncronas pueden enviar un registro de invocación, incluido el payload de respuesta, a un destino en caso de éxito o de falla. Una DLQ es la opción tentadora, pero solo captura los eventos fallidos y guarda el evento, no el resultado.", ["Una dead-letter queue recibe solo los eventos que fallaron todos los reintentos, nunca los resultados exitosos.", "Las suscripciones de logs reenvían líneas de log, no el registro de invocación con el payload devuelto, y requieren interpretarlas.", "La concurrencia reservada limita el escalado de la función de auditoría; no le envía nada.", null]],
  "x8": ["Una función Lambda lee un DynamoDB stream. Un registro mal formado hace que falle cada lote, y Lambda sigue reintentando ese shard, así que los cambios más nuevos del shard quedan atascados. ¿Qué cambios en el event source mapping resuelven MEJOR esto?", ["Aumentar el tamaño de lote para que el registro malo se mezcle con más registros buenos", "Habilitar bisect on error, limitar los intentos de reintento y agregar un destino on-failure", "Reducir la memoria de la función para que las invocaciones fallidas terminen antes y cuesten menos", "Cambiar el stream view type de NEW_AND_OLD_IMAGES a KEYS_ONLY"], "Para orígenes de tipo stream, BisectBatchOnFunctionError divide un lote que falla para aislar el registro malo, MaximumRetryAttempts (o la antigüedad del registro) detiene los reintentos interminables, y un destino on-failure conserva los detalles del registro omitido. Los lotes más grandes solo hacen que falle cada lote.", ["Un lote más grande sigue fallando completo cada vez que contiene el registro malo, así que el shard sigue bloqueado.", null, "Menos memoria no detiene los reintentos; el mismo registro sigue fallando y bloqueando el shard.", "El view type solo cambia qué datos lleva cada registro; el registro mal formado seguiría fallando al procesarse."]],
  "x9": ["Un productor envía mensajes a una cola SQS FIFO y a veces repite una llamada SendMessage después de un timeout de red, lo que crea duplicados. Los mensajes reintentados tienen cuerpos idénticos. ¿Cuál es la forma más sencilla de evitar los duplicados?", ["Habilitar la deduplicación basada en contenido en la cola", "Dar a cada mensaje su propio MessageGroupId único", "Habilitar long polling con un tiempo de espera de 20 segundos", "Establecer DelaySeconds en cero en cada llamada de envío"], "Con la deduplicación basada en contenido, SQS FIFO deriva el ID de deduplicación de un hash SHA-256 del cuerpo, así que los reintentos idénticos dentro del intervalo de deduplicación se descartan. MessageGroupId es tentador porque es específico de FIFO, pero controla el orden.", [null, "El grupo de mensajes controla el orden y el paralelismo, no la deduplicación; los duplicados se seguirían aceptando.", "El long polling cambia cómo reciben los consumidores, no si la cola acepta un envío repetido.", "La configuración de retraso solo pospone la entrega; no hace nada para reconocer un mensaje repetido."]],
  "x10": ["Un Kinesis data stream tiene 10 shards. Un shard devuelve ProvisionedThroughputExceededException mientras los demás están inactivos. Todos los productores usan la cadena constante 'events' como partition key. ¿Qué debe hacer el desarrollador?", ["Aumentar el periodo de retención de datos del stream", "Cambiar las aplicaciones consumidoras a enhanced fan-out", "Usar una partition key de alta cardinalidad, como el ID del dispositivo", "Fusionar shards para que el throughput se concentre en menos shards"], "La partition key se procesa con un hash para elegir un shard, así que una clave constante envía todos los registros a un solo shard. Una clave con muchos valores distintos reparte las escrituras de manera uniforme. Enhanced fan-out es tentador, pero resuelve las lecturas de los consumidores, no los puntos calientes de los productores.", ["La retención decide cuánto tiempo se guardan los registros, no cómo se reparten las escrituras entre shards.", "Enhanced fan-out mejora el throughput de lectura de los consumidores; el problema aquí es el desbalance de escritura de los productores.", null, "Fusionar shards reduce la capacidad total y no hace nada para repartir una clave constante entre shards."]],
  "x11": ["Cinco aplicaciones independientes leen el mismo Kinesis data stream y compiten por el throughput de lectura compartido de cada shard, así que su latencia de procesamiento crece. ¿Qué debe usar el desarrollador?", ["Poner una cola SQS entre el stream y cada app", "Registrar cada app como un consumidor de enhanced fan-out", "Aumentar el periodo de retención del Kinesis stream", "Aumentar el tamaño de lote usado en cada llamada GetRecords"], "Enhanced fan-out le da a cada consumidor registrado su propio throughput de lectura dedicado por shard, enviado por HTTP/2, así que los consumidores dejan de competir. Lotes más grandes de GetRecords son tentadores, pero siguen compartiendo el mismo límite por shard.", ["Agregar colas crea infraestructura y costo extra, y sigue dejando algo que lee del throughput compartido del shard.", null, "Una retención más larga conserva los registros por más tiempo, pero no les da más throughput a los lectores.", "Lotes más grandes por llamada siguen consumiendo del mismo límite de lectura compartido por shard."]],
  "x12": ["Varios microservicios publican eventos en un event bus personalizado de EventBridge. Una función Lambda debe ejecutarse solo para los eventos con source 'com.shop.orders' y detail-type 'OrderCancelled'. ¿Qué debe crear el desarrollador?", ["Una filter policy de SNS en un tema suscrito al event bus predeterminado", "Una función que reciba todos los eventos y termine de inmediato para los demás", "Un metric filter de CloudWatch Logs que busque el texto del evento", "Una regla en el bus personalizado cuyo event pattern coincida con source y detail-type"], "Las reglas de EventBridge usan event patterns para coincidir con campos como source y detail-type, y luego invocan solo los destinos que coinciden. Filtrar dentro de la función es el atajo tentador, pero se paga cada invocación innecesaria.", ["Las filter policies de SNS aplican a las suscripciones de SNS; aquí los eventos están en un bus personalizado de EventBridge, y el bus predeterminado es el bus equivocado.", "Recibir todos los eventos funciona, pero desperdicia invocaciones y costo cuando EventBridge puede filtrar antes de invocar.", "Los metric filters cuentan texto en los logs; no envían eventos a una función Lambda.", null]],
  "x13": ["Un proceso de pedidos abarca los servicios de pago, inventario y envíos. El equipo necesita un solo lugar para ver el paso actual de cada pedido, ejecutar acciones compensatorias cuando un paso falla y revisar el historial de ejecución. ¿Qué enfoque es el MÁS adecuado?", ["Coreografía, con cada servicio reaccionando a los eventos de EventBridge de los demás", "Llamadas HTTP síncronas encadenadas una tras otra desde el servicio de pago", "Una tabla de DynamoDB compartida que cada servicio consulta para descubrir cambios de estado", "Orquestación con una state machine de Step Functions que llame a cada servicio"], "La orquestación pone el flujo en un solo lugar: Step Functions muestra el estado y el historial de cada ejecución, y las rutas Catch pueden ejecutar pasos compensatorios. La coreografía es un patrón válido y tentador para desacoplar, pero no ofrece una vista central de cada pedido.", ["La coreografía mantiene los servicios poco acoplados, pero reparte el flujo entre los servicios, así que no hay una vista única del progreso ni compensación central.", "Las llamadas síncronas encadenadas acoplan fuertemente los servicios y no dan historial duradero ni manejo de errores integrado.", "Consultar una tabla compartida acopla los servicios a través de los datos, agrega latencia y sigue sin dejar un flujo ni historial central.", null]],
  "x14": ["Registrar un pedido debe descontar stock en una tabla Inventory e insertar una fila en una tabla Orders. Ambas escrituras deben tener éxito juntas o ninguna, y el stock nunca debe quedar negativo. ¿Qué debe usar el desarrollador?", ["BatchWriteItem con ambas solicitudes en una sola llamada a DynamoDB", "TransactWriteItems con una condition check de que el stock sea suficiente", "Dos llamadas PutItem separadas, reintentando cualquiera de ellas si falla", "Un DynamoDB stream sobre Orders que actualice después la tabla Inventory"], "Las transacciones de DynamoDB aplican todas las acciones de forma atómica entre tablas, y una ConditionExpression puede cancelar toda la transacción cuando el stock es demasiado bajo. BatchWriteItem es tentador porque agrupa escrituras, pero no es todo o nada.", ["BatchWriteItem no es atómico: algunas solicitudes pueden tener éxito mientras otras fallan, y no admite condition expressions.", null, "Las llamadas separadas pueden dejar una escritura aplicada y la otra no si el proceso falla entre ambas.", "Una actualización por stream ocurre después y por separado, así que las dos tablas pueden no coincidir y las verificaciones de stock no se hacen cumplir."]],
  "x15": ["Un desarrollador necesita una sort key alternativa en una tabla de DynamoDB existente y con datos (misma partition key) y requiere Query fuertemente consistentes sobre ella. ¿Cuál es la restricción?", ["Un LSI se puede agregar en cualquier momento, pero solo admite lecturas eventualmente consistentes", "Un GSI permite lecturas fuertemente consistentes si reutiliza la partition key de la tabla", "Los LSI solo se pueden definir al crear la tabla, así que se requiere una tabla nueva", "Ningún tipo de índice puede usar una sort key distinta de la de la tabla base"], "Un local secondary index comparte la partition key, permite lecturas fuertemente consistentes y debe crearse junto con la tabla. Un GSI se puede agregar después, pero sus lecturas son eventualmente consistentes, así que no cumple el requisito de consistencia fuerte.", ["Es al revés: un LSI admite lecturas fuertemente consistentes, pero no se puede agregar a una tabla existente.", "Los GSI admiten solo lecturas eventualmente consistentes, sin importar qué clave usen.", null, "Ambos tipos de índice existen precisamente para ofrecer una sort key (o un esquema de claves) distinta de la tabla base."]],
  "x16": ["Un usuario guarda un cambio en su perfil y recarga la página de inmediato, pero GetItem a veces devuelve el valor anterior. ¿Qué cambio hace que GetItem devuelva los datos confirmados más recientes?", ["Establecer ConsistentRead en true en la solicitud GetItem", "Agregar un global secondary index con clave en el atributo de ID de perfil", "Habilitar DynamoDB Streams en la tabla de perfiles", "Poner DynamoDB Accelerator (DAX) delante"], "GetItem es eventualmente consistente de forma predeterminada. Establecer ConsistentRead en true devuelve la escritura exitosa más reciente. DAX es tentador como mejora de rendimiento, pero su caché de ítems sirve resultados eventualmente consistentes.", [null, "Los GSI son eventualmente consistentes y no ayudarían a que GetItem sobre la tabla base devuelva datos más recientes.", "Streams captura los cambios para otros consumidores; no cambia lo que devuelve una lectura.", "DAX guarda en caché lecturas eventualmente consistentes, así que puede servir datos desactualizados en lugar de resolver el problema."]],
  "x17": ["Las facturas en PDF guardadas en S3 se leen con frecuencia durante 30 días, rara vez después, y deben eliminarse después de 7 años. ¿Cuál es la forma de administrarlas con el menor esfuerzo?", ["Una Lambda nocturna que copie los objetos viejos a otro bucket", "Reglas de lifecycle: transición después de 30 días y expiración después de 7 años", "Versionado con MFA Delete activado en el bucket de facturas", "Notificaciones de eventos que etiqueten los objetos cuando cumplan 30 días"], "Las configuraciones de S3 Lifecycle pueden hacer la transición de objetos a clases de almacenamiento más baratas después de cierta antigüedad y expirarlos más tarde, sin código. Un trabajo programado en Lambda es la respuesta tentadora hecha a mano, pero agrega código y operación para algo que ya es una función integrada.", ["El código de copia personalizado hay que escribirlo, ejecutarlo y monitorearlo, mientras que las reglas de lifecycle lo hacen de forma nativa.", null, "El versionado y MFA Delete protegen contra la eliminación; no mueven los datos a almacenamiento más barato ni los expiran.", "Las etiquetas por sí solas no cambian nada; algo más tendría que mover y eliminar los objetos."]],
  "x18": ["Varios equipos necesitan que su propia función Lambda reaccione a cada objeto nuevo en un bucket, y con el tiempo se agregarán más consumidores sin editar la configuración del bucket cada vez. ¿Qué diseño es el MÁS adecuado?", ["Agregar una notificación de eventos por función, todas con el mismo prefijo", "Que cada función liste el bucket cada minuto en busca de objetos nuevos", "Replicar el bucket en una copia separada que pertenezca a cada equipo", "Enviar los eventos de S3 a EventBridge y dar a cada consumidor su propia regla"], "Con EventBridge habilitado en el bucket, cada evento de objeto va al bus predeterminado, y cada equipo agrega su propia regla y destino sin tocar el bucket. Usar notificaciones de S3 separadas por función es tentador, pero falla con tipos de evento y prefijos superpuestos.", ["S3 no permite configuraciones de notificación superpuestas para el mismo tipo de evento y prefijo, y cada cambio implica editar el bucket.", "Listar de forma programada es lento, costoso a escala y pierde el sentido del procesamiento basado en eventos.", "La replicación multiplica el costo de almacenamiento y sigue necesitando notificaciones en cada copia.", null]],
  "x19": ["Una aplicación usa lazy loading con ElastiCache for Redis. Después de que cambian los precios en la base de datos, los usuarios siguen viendo precios viejos durante horas. ¿Cuál es la solución MÁS apropiada?", ["Dar un TTL a las keys en caché, y eliminar o actualizar las keys cuando se escriben los datos", "Pasar a un clúster de Memcached con más nodos", "Elegir un tipo de nodo más grande para que quepan más keys en memoria", "Habilitar Multi-AZ con failover automático en el clúster"], "Lazy loading solo actualiza una key cuando hay un cache miss, así que las entradas sin TTL pueden quedar desactualizadas indefinidamente. Un TTL acota qué tan desactualizadas quedan, e invalidar o hacer write-through en las actualizaciones lo elimina. Los nodos más grandes son tentadores, pero no afectan la frescura de los datos.", [null, "Cambiar de motor o de cantidad de nodos agrega capacidad, pero sigue sirviendo las mismas entradas desactualizadas.", "Más memoria solo mantiene las keys desactualizadas por más tiempo; el problema es la frescura de los datos.", "Multi-AZ mejora la disponibilidad, no qué tan rápido los valores en caché reflejan los cambios de la base de datos."]],
  "x20": ["Una app móvil usa un user pool de Cognito. Los usuarios deben permanecer con sesión iniciada durante semanas sin volver a escribir la contraseña, mientras los ID tokens y access tokens siguen siendo de corta duración. ¿Qué debe hacer la app?", ["Configurar la duración del access token en varias semanas", "Guardar la contraseña en el dispositivo e iniciar sesión en segundo plano", "Usar el refresh token para obtener nuevos ID tokens y access tokens", "Intercambiar el ID token por una API key de API Gateway"], "Cognito emite un refresh token junto con los ID tokens y access tokens; la app lo usa para obtener nuevos tokens de corta duración sin pedirle nada al usuario. Alargar el access token es tentador, pero debilita la seguridad.", ["Los access tokens de larga duración amplían el daño si alguien roba uno, que es justo lo que las duraciones cortas buscan evitar.", "Guardar contraseñas en los dispositivos es inseguro e innecesario cuando existen los refresh tokens.", null, "Las API keys identifican a quien llama para los usage plans; no son credenciales de usuario ni tokens de sesión."]],
  "x21": ["Una empresa vende acceso a su REST API y debe dar a cada cliente una cuota mensual de solicitudes y una tasa de throttling. ¿Qué debe configurar el desarrollador en API Gateway?", ["Un Cognito authorizer con un grupo por cliente", "Resource policies que enumeren los rangos de IP de los clientes", "API keys asociadas a usage plans", "Stage variables que contengan los límites de cada cliente"], "Los usage plans definen throttling y cuotas, y las API keys identifican a qué cliente se le cuenta cada solicitud. AWS aconseja no depender solo de las API keys para autorizar, así que combínalas con un authorizer. Los grupos de Cognito son tentadores, pero no miden el uso.", ["Los grupos de Cognito controlan la identidad y la autorización, no las cuotas ni el throttling por cliente.", "Las resource policies permiten o deniegan el acceso; no tienen un concepto de cuotas mensuales.", null, "Las stage variables pasan configuración a las integraciones; API Gateway no aplica límites a partir de ellas."]],
  "x22": ["Un Lambda authorizer basado en token se ejecuta en cada solicitud a la API, lo que agrega latencia y costo, aunque la política de un token sigue siendo válida durante varios minutos. ¿Qué debe hacer el desarrollador?", ["Habilitar la caché de resultados del authorizer con un TTL adecuado", "Habilitar la caché del stage de API Gateway para todos los métodos", "Darle más memoria a la función del authorizer", "Reemplazar el authorizer por una API key obligatoria en cada método"], "API Gateway puede guardar en caché la política que devuelve un Lambda authorizer, con el token (o las identity sources) como clave, durante un TTL configurado, así que las solicitudes repetidas se saltan el authorizer. La caché del stage suena parecida, pero aplica a las respuestas del backend.", [null, "La caché del stage guarda las respuestas de la integración, no las decisiones del authorizer, y podría servir los datos de un usuario a otro.", "Más memoria puede ahorrar un poco de tiempo, pero el authorizer sigue ejecutándose en cada solicitud.", "Las API keys no son un mecanismo de autenticación y eliminarían por completo la validación del token."]],
  "x23": ["Se creó un rol en la cuenta B para una app de la cuenta A. La política IAM de la app permite sts:AssumeRole sobre el ARN de ese rol, pero la llamada devuelve AccessDenied. ¿Qué es lo MÁS probable que falte?", ["El rol no tiene una session policy enviada junto con la llamada AssumeRole", "La cuenta A primero debe activar los endpoints de STS en la región de la cuenta", "La llamada debe hacerse con el usuario root de la cuenta A para cruzar cuentas", "La trust policy del rol no nombra a la cuenta A ni a su rol como principal"], "Asumir un rol entre cuentas necesita ambos lados: una política de identidad en A que permita sts:AssumeRole y una trust policy en el rol de B que confíe en A. Como el lado de quien llama ya está permitido, la trust policy faltante es la causa probable.", ["Las session policies son opcionales y solo pueden reducir permisos; su ausencia nunca bloquea AssumeRole.", "Los endpoints regionales de STS están activos de forma predeterminada en las regiones comerciales, y el error apunta a la autorización, no a un endpoint.", "Usar el usuario root es una mala práctica e innecesario; un principal IAM con la confianza adecuada puede asumir el rol.", null]],
  "x24": ["Una empresa debe mantener sus claves de cifrado completamente fuera de AWS, pero quiere que Amazon S3 realice el cifrado y el descifrado. ¿Qué opción es la adecuada?", ["SSE-KMS con una customer managed key que controle la empresa", "SSE-C, proporcionando la key en cada solicitud por HTTPS", "SSE-S3 con keys administradas por S3", "S3 Bucket Keys con SSE-KMS"], "Con SSE-C el cliente proporciona la key en cada solicitud; S3 la usa para cifrar o descifrar y no la guarda. Las customer managed keys de KMS son tentadoras porque las controla el cliente, pero siguen residiendo en AWS.", ["Las customer managed keys de KMS se guardan y se usan dentro de AWS KMS, lo que el requisito descarta.", null, "Las keys de SSE-S3 las crea y las guarda por completo AWS.", "Las Bucket Keys solo reducen las llamadas a KMS con SSE-KMS; las keys siguen viviendo en KMS."]],
  "x25": ["Los objetos de un bucket usan SSE-KMS con la AWS managed key aws/s3. Ahora el equipo necesita editar la key policy y permitir que otra cuenta de AWS descifre los datos. ¿Qué debe hacer?", ["Crear una customer managed key y cifrar con SSE-KMS usándola", "Editar directamente la key policy de la AWS managed key aws/s3", "Cambiar el cifrado predeterminado del bucket a SSE-S3", "Habilitar S3 Bucket Keys en la AWS managed key aws/s3"], "Solo las customer managed keys de KMS permiten escribir la key policy, otorgar acceso a otras cuentas y controlar la rotación. Las AWS managed keys como aws/s3 son cómodas, pero sus políticas son fijas, por eso no se pueden editar.", [null, "Las políticas de las AWS managed keys no se pueden editar, así que no pueden otorgar acceso a otra cuenta.", "SSE-S3 no tiene ninguna key policy, así que no habría nada que otorgar ni controlar.", "Las Bucket Keys reducen el volumen de solicitudes a KMS; no cambian quién controla la key policy."]],
  "x26": ["Una aplicación necesita guardar un documento de configuración de 6 KB en Systems Manager Parameter Store y que expire automáticamente mediante una parameter policy. ¿Qué opción funciona?", ["Un parámetro SecureString del tier estándar", "Un parámetro StringList del tier estándar", "Un parámetro del tier avanzado", "Un String del tier estándar con una etiqueta"], "Los parámetros del tier avanzado permiten valores de hasta 8 KB y admiten parameter policies como Expiration. Los parámetros estándar llegan como máximo a 4 KB y no tienen políticas. SecureString es tentador porque suena más potente, pero es un tipo, no un tier.", ["Los parámetros estándar están limitados a 4 KB y no pueden usar parameter policies, sin importar su tipo.", "StringList sigue siendo un parámetro estándar, así que se mantienen el límite de tamaño y la falta de políticas.", null, "Las etiquetas son solo alias de versión; no aumentan el límite de tamaño ni agregan expiración."]],
  "x27": ["Los usuarios obtienen credenciales de AWS mediante un identity pool de Cognito. Cada usuario debe leer y escribir solo objetos bajo un prefijo de S3 que coincida con su propio identity ID. ¿Cuál es el MEJOR enfoque?", ["Un rol IAM separado creado para cada usuario en el momento en que se registra", "Un solo rol autenticado cuya política use la variable sub de cognito-identity en el ARN", "Una bucket policy que enumere uno por uno el ARN de identidad de cada usuario", "Presigned URLs para todos los objetos, regeneradas una vez al día para cada usuario"], "Las variables de políticas IAM como ${cognito-identity.amazonaws.com:sub} se resuelven en cada solicitud, así que un solo rol puede restringir a cada usuario a su propio prefijo. Los roles por usuario parecen precisos, pero no escalan.", ["Los roles por usuario no escalan y rápidamente chocan con las cuotas de IAM y la carga de administración.", null, "Una bucket policy que enumere a cada usuario crece sin límite y debe editarse en cada registro.", "Las presigned URLs diarias otorgan acceso amplio y de larga duración y no limitan las cargas al prefijo propio de cada usuario."]],
  "x28": ["Una función Lambda lee un secreto de base de datos desde Secrets Manager en cada invocación, lo que agrega latencia y llamadas a la API. El secreto se rota periódicamente. ¿Cuál es la MEJOR práctica?", ["Copiar el valor del secreto en una variable de entorno al momento del despliegue", "Incluir el valor del secreto en el paquete de despliegue de la función", "Desactivar la rotación para que el valor pueda guardarse en caché todo el tiempo necesario", "Guardar el secreto en caché fuera del handler y refrescarlo periódicamente"], "Guardar el secreto en caché en el entorno de ejecución (por ejemplo, con un cliente con caché o con la extensión Parameters and Secrets de Lambda) con un intervalo de refresco reduce las llamadas y aun así toma los valores rotados. Una variable de entorno es tentadora, pero queda desactualizada.", ["Una copia hecha al desplegar queda desactualizada en la siguiente rotación y expone el valor en la configuración de la función.", "Los secretos en el paquete de despliegue quedan expuestos a cualquiera que pueda descargar el código y nunca se rotan.", "Desactivar la rotación sacrifica un control de seguridad para resolver un problema de rendimiento que la caché resuelve.", null]],
  "x29": ["Una REST API debe ser accesible solo desde una VPC a través de un interface VPC endpoint para API Gateway. ¿Qué debe configurar el desarrollador?", ["Una API key obligatoria en cada método de la API", "Un Cognito user pool authorizer en cada método", "Un usage plan que aplique un límite de throttling muy bajo a todos los clientes", "Una API privada con una resource policy que permita ese endpoint"], "Las REST APIs privadas solo son accesibles a través de interface VPC endpoints, y una resource policy que use aws:SourceVpce (o aws:SourceVpc) limita el acceso al endpoint aprobado. Un Cognito authorizer es tentador, pero controla quién, no desde dónde.", ["Las API keys no son un límite de control de acceso y no hacen nada para restringir el origen de red.", "Un Cognito authorizer verifica la identidad del usuario, pero deja la API accesible desde cualquier lugar.", "El throttling limita la tasa de solicitudes; no restringe de dónde vienen.", null]],
  "x30": ["La política de identidad de un rol permite dynamodb:PutItem sobre una tabla, pero el permissions boundary asociado al rol solo permite dynamodb:GetItem. ¿Qué pasa cuando el rol llama a PutItem?", ["Se permite, porque las políticas de identidad tienen prioridad sobre los permissions boundaries", "Se deniega, porque los permisos efectivos son la intersección de ambos", "Se permite, pero solo si la tabla también tiene una resource-based policy", "Se deniega solo para los ítems mayores que el límite de tamaño de ítem de la tabla"], "Un permissions boundary pone un tope a lo que pueden otorgar las políticas de identidad: una acción debe estar permitida por ambos. PutItem está fuera del boundary, así que se deniega implícitamente. Pensar que la política de identidad gana es el error común.", ["Los boundaries no quedan por debajo; fijan el máximo que puede otorgar una política de identidad.", null, "Nada de la política de la tabla cambia esto; una resource policy que nombre al rol sigue limitada por el permissions boundary del rol.", "El tamaño del ítem es irrelevante para la autorización IAM; simplemente la acción no está permitida."]],
  "x31": ["Un juego permite probarlo sin iniciar sesión, y estos invitados necesitan credenciales temporales de AWS limitadas para escribir puntajes en una tabla de DynamoDB. ¿Qué debe habilitar el desarrollador?", ["Un app client de un user pool de Cognito creado sin client secret", "Un solo usuario IAM cuyas access keys compartan todos los jugadores invitados", "Identidades de invitado (no autenticadas) en un identity pool de Cognito", "Una resource policy en la tabla que permita escrituras públicas anónimas"], "Los identity pools pueden emitir credenciales temporales a identidades no autenticadas, asignadas a un rol de invitado con permisos muy acotados. La opción del user pool es tentadora porque también es Cognito, pero los user pools autentican usuarios en lugar de entregar credenciales de AWS.", ["Un app client de un user pool maneja el inicio de sesión de usuarios registrados; no entrega credenciales de AWS a invitados.", "Las keys compartidas de larga duración incrustadas en un cliente se pueden extraer y abusar, y no se pueden limitar por jugador.", null, "Permitir escrituras públicas anónimas elimina todo control sobre quién puede modificar la tabla."]],
  "x32": ["Una presigned URL de GET generada dentro de una función Lambda deja de funcionar mucho antes del tiempo de expiración que pidió el código. ¿Cuál es la razón MÁS probable?", ["Se firmó con las credenciales temporales del rol, que expiraron antes", "Las presigned URLs solo funcionan para solicitudes PutObject, nunca para GetObject", "El cifrado predeterminado del bucket es SSE-S3, que bloquea el acceso con presigned URLs", "El objeto está guardado en la clase S3 Standard, que limita la duración de la URL"], "Una presigned URL es válida solo mientras las credenciales que la firmaron sean válidas. Las credenciales del execution role de Lambda son temporales, así que una URL puede expirar cuando ellas expiran, aunque se haya pedido una expiración más larga. Culpar al cifrado es una suposición tentadora pero incorrecta.", [null, "Las presigned URLs admiten GET además de PUT y otras operaciones.", "SSE-S3 es transparente para las solicitudes autorizadas, incluidas las de presigned URLs.", "La clase de almacenamiento no afecta cuánto tiempo es válida una presigned URL."]],
  "x33": ["Un desarrollador quiere que cada operación de descifrado de KMS falle a menos que quien llama proporcione el mismo ID de tenant que se usó al cifrar, y quiere que el ID de tenant quede registrado en CloudTrail. ¿Qué debe usar?", ["Una data key guardada en caché por separado para cada tenant", "Un encryption context que incluya el ID de tenant", "Un alias de key separado creado para cada tenant de la cuenta", "Un grant sin restricciones para el rol de cada tenant"], "Un encryption context son datos autenticados adicionales no secretos: se debe proporcionar el mismo contexto para descifrar, y aparece en los logs de CloudTrail. Los alias por tenant son tentadores, pero solo nombran keys.", ["Guardar data keys en caché por tenant no hace que el descifrado dependa de presentar un ID de tenant.", null, "Los alias son nombres amigables para las keys; no vinculan el texto cifrado a un valor de tenant.", "Un grant sin restricciones da acceso, pero no exige ningún contexto coincidente."]],
  "x34": ["Una tarea de ECS en Fargate debe leer un bucket de S3 desde el código de la aplicación. La task definition tiene un task execution role que puede descargar imágenes de ECR, pero la app recibe AccessDenied. ¿Qué se debe corregir?", ["Agregar acceso de lectura a S3 en la resource policy del repositorio de ECR", "Asociar un instance profile de EC2 a la task definition de Fargate", "Aplicar al bucket una bucket policy public-read para la tarea", "Agregar un task role con permisos de S3 para que lo use la aplicación"], "El task execution role lo usa el agente de ECS para descargar imágenes y enviar logs; el task role proporciona credenciales al código de la aplicación. Agregar acceso a S3 al execution role es el error tentador, porque la app no usa esas credenciales.", ["La política del repositorio de ECR rige el acceso a las imágenes y no tiene nada que ver con los permisos de S3.", "Las tareas de Fargate no tienen instancias EC2 a las que asociar un profile; las tareas usan task roles.", "Hacer público el bucket expone los datos a todos en lugar de darle a la tarea el mínimo privilegio.", null]],
  "x35": ["Una función Lambda registra en los logs cada evento entrante completo, incluidos los headers Authorization que llevan bearer tokens. ¿Cuál es la MEJOR solución?", ["Dejar de registrar los eventos crudos; registrar solo los campos necesarios y ocultar los secretos", "Reducir el periodo de retención del log group a un solo día", "Cifrar el log group con una key de KMS y seguir registrando el evento completo", "Deshabilitar CloudWatch Logs para la función para ocultar los tokens"], "Los valores sensibles nunca deben escribirse en los logs; registra solo lo que se necesita para diagnosticar y oculta las credenciales. Cifrar el log group es tentador porque suena seguro, pero los lectores autorizados seguirían viendo los tokens.", [null, "Una retención corta sigue exponiendo los tokens a cualquiera que lea los logs durante ese periodo.", "El cifrado en reposo protege el almacenamiento, pero cualquiera con permiso para leer los logs sigue viendo los tokens.", "Desactivar los logs elimina la capacidad de diagnosticar en lugar de corregir lo que se está registrando."]],
  "x36": ["En una plantilla de AWS SAM, ¿qué declaración le indica a CloudFormation que procese tipos de recursos de SAM como AWS::Serverless::Function?", ["AWSTemplateFormatVersion: '2010-09-09'", "Resources: con una propiedad Type de SAM", "Transform: AWS::Serverless-2016-10-31", "Metadata: con una sección de herramienta SAM"], "La línea Transform invoca la macro AWS::Serverless, que expande los recursos de SAM en recursos estándar de CloudFormation. AWSTemplateFormatVersion es tentador porque también está al inicio de las plantillas, pero no expande nada.", ["La versión de formato identifica la sintaxis de la plantilla, pero no expande los tipos de recursos de SAM.", "Los recursos serverless se declaran en Resources, pero solo se expanden gracias a Transform.", null, "Metadata contiene información adicional sobre la plantilla y no dispara ningún procesamiento."]],
  "x37": ["Un desarrollador ejecutó sam deploy --guided una vez y quiere que los despliegues posteriores reutilicen el mismo nombre de stack, la misma región y los mismos valores de parámetros sin preguntas. ¿Dónde guarda SAM estas opciones?", ["La sección Outputs", "buildspec.yml", "samconfig.toml", "appspec.yml"], "El despliegue guiado ofrece guardar sus respuestas en samconfig.toml, y las ejecuciones posteriores de sam deploy las leen. buildspec.yml es tentador porque también es un archivo de configuración de la cadena de herramientas, pero pertenece a CodeBuild.", ["Outputs devuelve valores de un stack desplegado; no guarda configuraciones de despliegue.", "buildspec.yml configura los builds de CodeBuild, no los despliegues de SAM CLI.", null, "appspec.yml configura los despliegues y los lifecycle hooks de CodeDeploy."]],
  "x38": ["El primer cdk deploy en una cuenta y región nuevas falla porque no existen los recursos que CDK necesita, como un bucket de S3 para los assets. ¿Qué se debe ejecutar primero?", ["cdk bootstrap", "cdk synth --all", "cdk diff", "cdk init"], "cdk bootstrap despliega el toolkit stack (bucket de staging, roles y recursos relacionados) que los despliegues de CDK necesitan en cada cuenta y región. cdk synth es tentador porque también se ejecuta antes de los despliegues, pero solo escribe una salida local.", [null, "synth solo produce la plantilla localmente; no crea nada en la cuenta.", "diff compara con un stack desplegado y no crea los recursos que faltan.", "init crea el esqueleto de un proyecto local nuevo, no recursos en la cuenta."]],
  "x39": ["Sin usar CodeDeploy, un desarrollador quiere que el alias prod de una función Lambda envíe el 5% de las invocaciones a la versión 8 y el resto a la versión 7. ¿Qué debe configurar?", ["Dos alias con el mismo nombre, uno para cada versión", "Una Lambda layer que apunte la función al código de la versión 8", "Concurrencia reservada en la versión 8 igual al 5% del límite de la cuenta", "Enrutamiento ponderado en el alias, agregando la versión 8 como versión adicional"], "Un alias de Lambda puede apuntar a dos versiones con una configuración de enrutamiento que envía un peso determinado a la versión adicional. CodeDeploy automatiza el mismo mecanismo. La concurrencia reservada es tentadora, pero controla la capacidad, no la proporción de tráfico.", ["Los nombres de alias deben ser únicos dentro de una función, así que dos alias no pueden compartir nombre.", "Las layers contienen código o dependencias compartidas; no enrutan invocaciones entre versiones.", "La configuración de concurrencia pone un tope al escalado y no divide el tráfico por porcentaje.", null]],
  "x40": ["Un equipo quiere enviar el 10% del tráfico de un stage de REST API a un nuevo despliegue de la API y comparar sus métricas antes de promoverlo. ¿Qué función de API Gateway es la adecuada?", ["Una mock integration en la API", "Un canary release en el stage", "Un usage plan para el stage", "Un tipo de endpoint edge-optimized"], "La configuración canary del stage enruta un porcentaje elegido de solicitudes a un despliegue canary, con logs y métricas separados, y luego se puede promover. Los usage plans son tentadores porque también se asocian a stages, pero solo miden el uso.", ["Las mock integrations devuelven respuestas fijas sin backend; no dividen el tráfico.", null, "Los usage plans miden y aplican throttling a quienes tienen API keys; no enrutan entre despliegues.", "El tipo de endpoint controla cómo llegan los clientes a la API, no cómo se divide el tráfico entre despliegues."]],
  "x41": ["En un despliegue blue/green de CodeDeploy en Amazon ECS, el equipo quiere que las pruebas se ejecuten contra el task set de reemplazo a través del test listener antes de mover cualquier tráfico de producción. ¿Qué lifecycle hook debe invocar la función de pruebas?", ["AfterAllowTestTraffic", "BeforeInstall", "ApplicationStart", "ValidateService"], "Los hooks del appspec de ECS son BeforeInstall, AfterInstall, AfterAllowTestTraffic, BeforeAllowTraffic y AfterAllowTraffic. AfterAllowTestTraffic se ejecuta una vez que el test listener envía tráfico a las tareas nuevas. ValidateService es tentador por los despliegues en EC2, pero no aplica.", [null, "BeforeInstall se ejecuta antes de crear el task set de reemplazo, así que todavía no hay nada que probar.", "ApplicationStart es un hook de EC2/on-premises y no está disponible para despliegues en ECS.", "ValidateService es un hook de EC2/on-premises; los despliegues en ECS usan en su lugar los hooks basados en tráfico."]],
  "x42": ["Un despliegue de CodeDeploy para un alias de Lambda debe ejecutar una función de validación antes de que se mueva cualquier tráfico a la nueva versión. ¿Qué hook del appspec debe llamarla?", ["AfterInstall", "ApplicationStop", "BeforeAllowTraffic", "DownloadBundle"], "Los despliegues de Lambda admiten dos hooks: BeforeAllowTraffic (antes de mover el tráfico) y AfterAllowTraffic (después). AfterInstall es tentador por los appspec de EC2, pero los despliegues de Lambda no lo tienen.", ["AfterInstall no es uno de los hooks que admite un despliegue de Lambda.", "ApplicationStop es un hook de EC2/on-premises para detener la aplicación anterior.", null, "DownloadBundle es un evento de EC2 administrado por CodeDeploy y no puede ejecutar scripts ni funciones."]],
  "x43": ["Una app de producción en Elastic Beanstalk debe mantener toda su capacidad de atención durante los despliegues, pero el equipo quiere un costo menor que lanzar un segundo conjunto completo de instancias. ¿Qué política de despliegue es la MÁS adecuada?", ["Immutable", "Rolling with an additional batch", "All at once", "Rolling"], "Rolling with an additional batch lanza primero un lote extra, así que la capacidad nunca baja, y solo agrega un lote de instancias. Immutable es la respuesta tentadora porque también conserva la capacidad, pero duplica la flota durante el despliegue.", ["Immutable mantiene la capacidad, pero lanza un conjunto paralelo completo de instancias, que es el costo extra que el equipo quiere evitar.", null, "All at once saca de servicio todas las instancias a la vez, así que la capacidad cae brevemente a cero.", "Rolling simple saca lotes de servicio, así que la capacidad se reduce durante el despliegue."]],
  "x44": ["Un equipo quiere que Elastic Beanstalk envíe un porcentaje del tráfico de clientes a las instancias con la nueva versión durante un periodo de evaluación, y que vuelva atrás si las instancias nuevas no están sanas. ¿Qué política es la adecuada?", ["Rolling", "All at once", "Rolling with an additional batch", "Traffic splitting"], "Los despliegues con traffic splitting lanzan instancias nuevas y les envían un porcentaje determinado del tráfico durante un tiempo de evaluación; si fallan los health checks, el tráfico vuelve a la versión anterior. Rolling with an additional batch es tentador, pero no tiene una división de tipo canary.", ["Rolling reemplaza instancias lote por lote sin enviar una porción controlada del tráfico a la nueva versión.", "All at once cambia todas las instancias a la vez, sin periodo de evaluación.", "Esta política mantiene la capacidad durante una actualización rolling, pero no divide el tráfico para evaluar.", null]],
  "x45": ["Un proyecto de CodeBuild compila una aplicación Java, pero la siguiente etapa del pipeline recibe un artefacto de salida vacío. El buildspec solo tiene las fases install y build. ¿Qué falta?", ["Una fase post_build que imprima un mensaje", "Una sección env que defina la variable JAVA_HOME", "Una sección cache para las dependencias de Maven", "Una sección artifacts que enumere los archivos de salida"], "CodeBuild solo sube los archivos indicados en la sección artifacts del buildspec (por ejemplo, target/*.jar). Sin ella, el artefacto de salida queda vacío. Una fase post_build es tentadora porque se ejecuta al final, pero no empaqueta la salida.", ["Una fase post_build ejecuta comandos, pero por sí sola no declara qué archivos se convierten en el artefacto.", "El build se ejecutó, así que el entorno está bien; las variables de env no publican salidas.", "La caché acelera los builds, pero no tiene nada que ver con qué archivos se entregan a la siguiente etapa.", null]],
  "x46": ["Un buildspec necesita una contraseña de base de datos durante las pruebas de integración, y la contraseña no debe guardarse en el repositorio. ¿Cuál es el MEJOR enfoque?", ["Escribir la contraseña directamente en el archivo buildspec.yml", "Referenciarla desde Secrets Manager en la sección env del buildspec", "Subirla al repositorio dentro de un archivo zip cifrado", "Ingresarla como variable de entorno en texto plano en la consola"], "La sección env del buildspec puede obtener valores de Secrets Manager (secrets-manager) o Parameter Store (parameter-store) durante el build, así que no se sube nada sensible. Una variable en texto plano en la consola es tentadora, pero expone el valor.", ["Todo lo que se escribe en buildspec.yml termina en el control de versiones, lo que el requisito prohíbe.", null, "Un zip cifrado sigue guardando el secreto en el repositorio y necesita su propio manejo de claves.", "Las variables del proyecto en texto plano son visibles para cualquiera que pueda ver la configuración del proyecto de build."]],
  "x47": ["Una actualización de un stack de CloudFormation falla a mitad de camino. ¿Qué hace CloudFormation de forma predeterminada?", ["Conserva los recursos actualizados y elimina el stack", "Reintenta el recurso fallido hasta que la actualización tenga éxito", "Hace rollback del stack a su último estado funcional conocido", "Elimina el stack junto con todos sus recursos"], "De forma predeterminada, una actualización de stack fallida se revierte y los recursos vuelven a su última configuración estable (UPDATE_ROLLBACK_COMPLETE). Eliminar el stack es una suposición tentadora porque las creaciones fallidas pueden terminar en eliminación, pero las actualizaciones se revierten.", ["CloudFormation no conserva un stack actualizado a medias para luego eliminarlo; restaura el estado anterior.", "No hay reintentos interminables; la actualización fallida dispara un rollback.", null, "Eliminar todo el stack por una actualización fallida destruiría recursos que funcionan; ese no es el comportamiento predeterminado."]],
  "x48": ["Un equipo publicó la versión 5 de una Lambda y apuntó el alias prod a ella. Después, un desarrollador edita el código en la consola sin publicar. ¿Qué ejecutan quienes llaman al alias prod?", ["La versión 5, ya que las versiones publicadas no pueden cambiar", "El código editado, porque los alias siguen a $LATEST", "Un error hasta que se publique una nueva versión", "La versión 5 y $LATEST de forma alternada, solicitud por solicitud"], "Las versiones publicadas son instantáneas inmutables, y un alias sigue apuntando a la versión que nombra. Las ediciones solo afectan a $LATEST hasta que se publica una nueva versión y se actualiza el alias. Suponer que los alias siguen a $LATEST es la trampa común.", [null, "Un alias apunta a la versión que se le asignó; solo una llamada sin calificar o a $LATEST usa el código editado.", "Editar $LATEST no rompe un alias que apunta a una versión publicada.", "El tráfico solo se divide cuando hay una configuración de enrutamiento en el alias."]],
  "x49": ["Un pipeline despliega una API serverless en un stage de prueba. El equipo quiere que el pipeline se detenga antes de producción si fallan las pruebas end-to-end contra ese stage desplegado. ¿Qué debe agregar?", ["Una acción de aprobación manual antes del despliegue en el stage de prueba", "Una acción de prueba de CodeBuild después del despliegue de prueba que falle si hay errores en las pruebas", "Más pruebas unitarias en la fase build que usen servicios de AWS simulados", "Detección de drift de CloudFormation ejecutada después contra el stack de prueba"], "Una acción de prueba (por ejemplo, CodeBuild ejecutando la suite de integración contra la URL del stage de prueba) que haga fallar la etapa ante cualquier prueba fallida detiene el pipeline antes de producción. Las pruebas unitarias con mocks son tentadoras, pero no ejercitan el entorno desplegado.", ["Una aprobación manual antes del despliegue no prueba nada y depende de una persona en lugar de resultados.", null, "Las pruebas unitarias con mocks se ejecutan antes del despliegue y no pueden demostrar que el stage desplegado funcione de punta a punta.", "La detección de drift encuentra configuraciones cambiadas fuera de CloudFormation; no prueba el comportamiento de la API."]],
  "x50": ["Una API de alto tráfico instrumentada con X-Ray produce un gran volumen de trazas y un costo creciente. El equipo quiere una muestra pequeña y representativa, pero todas las solicitudes de una ruta crítica de checkout. ¿Qué debe configurar?", ["Deshabilitar el active tracing en todas las funciones detrás de la API", "Registrar todos los detalles como metadata en lugar de annotations", "Aumentar el tamaño de buffer que usa el daemon de X-Ray", "Sampling rules personalizadas: una tasa predeterminada baja más una regla de checkout con mayor prioridad"], "Las sampling rules de X-Ray coinciden con atributos como la ruta de la URL y se evalúan por prioridad, así que una regla puede muestrear checkout a una tasa alta mientras la regla predeterminada muestrea todo lo demás con moderación. Deshabilitar el tracing reduce el costo, pero pierde los datos necesarios.", ["Desactivar el tracing elimina por completo la visibilidad, incluida la de la ruta crítica.", "Metadata o annotations cambia la indexación, no cuántas trazas se registran.", "El tamaño del buffer afecta cómo el daemon agrupa las cargas, no cuántas solicitudes se muestrean.", null]],
  "x51": ["Un desarrollador quiere que X-Ray muestre cuánto tiempo pasa una función llamando a una API de pagos externa en comparación con su propio procesamiento. ¿Qué debe agregar?", ["Un subsegmento alrededor de la llamada a la API de pagos", "Una annotation que guarde la duración", "Un metric filter en el log group de la función", "Un segundo grupo de X-Ray para las trazas de pagos"], "Los subsegmentos registran el tiempo de una llamada downstream o de un bloque de código específico dentro de un segmento, así que la línea de tiempo de la traza muestra esa llamada por separado. Una annotation es tentadora, pero solo indexa valores para filtrar.", [null, "Una annotation agrega un valor que se puede buscar, pero no produce un bloque con tiempo en la línea de tiempo de la traza.", "Un metric filter cuenta patrones en los logs y no aparece en el desglose de la traza.", "Los grupos filtran trazas por expresión; no miden el tiempo de una sección de código."]],
  "x52": ["Una aplicación necesita una métrica personalizada de CloudWatch con granularidad de 1 segundo y una alarma que evalúe cada 10 segundos. ¿Qué debe usar el desarrollador?", ["Una métrica de resolución estándar publicada cada segundo", "Una consulta programada de CloudWatch Logs Insights", "Una métrica de alta resolución con una alarma de alta resolución", "Las cifras de latencia del service map de X-Ray"], "Publicar con StorageResolution 1 crea una métrica de alta resolución, y las alarmas sobre ella pueden usar periodos de 10 o 30 segundos. Publicar una métrica estándar cada segundo es tentador, pero CloudWatch la agrega a un minuto.", ["Las métricas de resolución estándar se guardan con granularidad de 1 minuto, sin importar con qué frecuencia se publiquen.", "Las consultas de Logs Insights son para análisis puntual, no para evaluar alarmas cada 10 segundos.", null, "El service map visualiza trazas; no proporciona métricas personalizadas ni alarmas."]],
  "x53": ["Una función Lambda escribe en una base de datos heredada que acepta solo un número limitado de conexiones. Durante los picos de tráfico, la función escala y satura la base de datos. ¿Cuál es el control más sencillo?", ["Habilitar provisioned concurrency en el alias de la función", "Aumentar la memoria de la función para acelerar cada llamada", "Configurar concurrencia reservada para limitar cuántas copias se ejecutan", "Agregar una annotation de X-Ray a las solicitudes a la base de datos"], "La concurrencia reservada fija un máximo de ejecuciones concurrentes para la función, lo que protege un recurso downstream frágil. Provisioned concurrency es la confusión tentadora; se trata de arranques en caliente, no de un techo.", ["Provisioned concurrency precalienta entornos; no impide que la función escale más allá de ese número.", "Llamadas más rápidas no limitan cuántas se ejecutan a la vez, así que las conexiones pueden seguir disparándose.", null, "Las annotations ayudan a filtrar trazas, pero no controlan el escalado."]],
  "x54": ["Después de que un equipo configura un valor alto de concurrencia reservada en una función Lambda, otras funciones de la misma cuenta y región empiezan a sufrir throttling durante los picos. ¿Por qué?", ["La concurrencia reservada se toma del pool no reservado que comparten las demás funciones", "La concurrencia reservada duplica la memoria de todas las demás funciones de la región", "Configurar concurrencia reservada desactiva el escalado de todas las demás funciones de la cuenta", "La concurrencia reservada hace más largos los cold starts de todas las funciones de la cuenta"], "La concurrencia de la cuenta se comparte por región. Reservar una parte para una función la quita del pool no reservado, así que las demás funciones pueden llegar al techo restante, que es más bajo, y sufrir throttling. Suponer que se desactivó el escalado es tentador, pero simplemente les falta pool.", [null, "La configuración de concurrencia nunca cambia la memoria de ninguna función.", "Las demás funciones siguen escalando, pero solo dentro de lo que queda del pool no reservado.", "El tiempo de cold start no tiene relación; el throttling viene de la menor concurrencia disponible."]],
  "x55": ["Después de corregir un bug, un desarrollador quiere mover los mensajes de una dead-letter queue de SQS de vuelta a la cola de origen para reprocesarlos con el mínimo código. ¿Qué debe usar?", ["Purgar la DLQ y pedir a los productores que vuelvan a enviar cada mensaje", "Convertir la dead-letter queue en una cola FIFO", "Extender el periodo de retención de la dead-letter queue", "El redrive de la dead-letter queue hacia la cola de origen"], "SQS admite el redrive de DLQ, que mueve los mensajes de la dead-letter queue de vuelta a la cola de origen (o a otra cola) desde la consola o la API. Extender la retención es tentador como medida de seguridad, pero no reprocesa nada.", ["Purgar elimina los mensajes fallidos, y los productores quizá no puedan recrearlos.", "El tipo de una cola no se puede cambiar después de crearla, y hacerlo tampoco movería los mensajes.", "Una retención más larga conserva los mensajes, pero no los devuelve para procesarlos.", null]],
  "x56": ["Un equipo quiere una alarma cada vez que el texto 'PaymentDeclined' aparezca en los logs de la aplicación más de 20 veces en 5 minutos. ¿Qué se debe crear primero?", ["Un grupo de X-Ray con una filter expression para los errores de pago rechazado", "Un metric filter en el log group que cuente esos eventos", "Una consulta guardada de CloudWatch Logs Insights para el texto", "Un trail de CloudTrail que capture los eventos de la aplicación"], "Un metric filter convierte los eventos de log que coinciden en una métrica de CloudWatch, y luego una alarma puede dispararse cuando el conteo supere 20 en 5 minutos. Una consulta guardada de Logs Insights es tentadora, pero es una herramienta de análisis, no una métrica.", ["Los grupos de X-Ray filtran trazas, no texto arbitrario de los logs.", null, "Las consultas guardadas de Insights se ejecutan a demanda y por sí solas no producen una métrica sobre la cual alarmar.", "CloudTrail registra llamadas a APIs de AWS, no el texto que se escribe en los logs de la aplicación."]],
  "x57": ["Una aplicación nueva tiene tráfico impredecible en DynamoDB que pasa de casi cero a picos grandes y repentinos, y el equipo no quiere administrar capacidad. ¿Qué opción es la adecuada?", ["Modo de capacidad on-demand", "Modo provisionado con capacidad fija baja", "Modo provisionado con escalado programado", "DAX sin ninguna tabla de DynamoDB"], "El modo on-demand cobra por solicitud y se adapta automáticamente al tráfico, lo que sirve para cargas con picos e impredecibles sin planificar capacidad. El escalado programado es tentador, pero solo ayuda cuando los picos son predecibles.", [null, "Un valor provisionado fijo y bajo aplicará throttling durante los picos.", "El escalado programado necesita horarios predecibles, que esta carga de trabajo no tiene.", "DAX es una caché que se ubica delante de una tabla; no puede reemplazarla."]],
  "x58": ["Una función Lambda se conectó a subredes privadas que no tienen NAT gateway ni VPC endpoints. Ahora sus llamadas a DynamoDB se quedan colgadas hasta que la función registra 'Task timed out'. ¿Cuál es la MEJOR solución?", ["Subir el timeout a 15 minutos para que las llamadas tengan tiempo de terminar", "Aumentar la memoria para que la función tenga más ancho de banda de red", "Agregar un gateway VPC endpoint de DynamoDB a las tablas de rutas de las subredes", "Habilitar active tracing de X-Ray en la función para resolver la conectividad"], "Una función conectada a una VPC usa el enrutamiento de la VPC; sin NAT ni endpoint no puede llegar a los endpoints públicos de los servicios. Un gateway endpoint de DynamoDB agrega una ruta privada. Subir el timeout es tentador, pero las solicitudes nunca se completarán.", ["Las llamadas nunca pueden llegar a DynamoDB sin una ruta, así que un timeout más largo solo retrasa la falla.", "Más memoria no crea una ruta de red para salir de las subredes privadas.", null, "El tracing puede mostrar en qué se va el tiempo, pero no proporciona conectividad."]],
  "x59": ["Un desarrollador quiere encontrar qué invocaciones de Lambda usaron más memoria en el último día. ¿Dónde están estos datos más fácilmente disponibles?", ["Los management events de CloudTrail registrados para la función", "Las líneas REPORT de los logs, consultadas con Logs Insights", "El service map de X-Ray de la aplicación", "Los hallazgos de IAM Access Analyzer para el rol"], "Cada invocación escribe una línea REPORT con la duración, la duración facturada y la memoria máxima usada, y Logs Insights expone campos como @maxMemoryUsed para ordenar. X-Ray es tentador para preguntas de rendimiento, pero no reporta memoria.", ["Los management events registran llamadas a APIs como UpdateFunctionConfiguration, no el uso de memoria por invocación.", null, "El service map muestra las conexiones entre servicios y la latencia, no la memoria usada por invocación.", "Access Analyzer revisa permisos y accesos externos, no métricas de tiempo de ejecución."]],
  "x60": ["Una función Lambda en Java tiene cold starts largos causados por una inicialización pesada. El equipo quiere reducirlos sin pagar para mantener entornos calientes todo el tiempo. ¿Qué función es la adecuada?", ["Provisioned concurrency en el alias de la función", "Concurrencia reservada en la función", "Un almacenamiento efímero /tmp más grande", "Lambda SnapStart en las versiones publicadas"], "SnapStart toma una instantánea del entorno de ejecución inicializado cuando se publica una versión y se reanuda desde ella, lo que reduce el tiempo de cold start sin entornos siempre encendidos. Provisioned concurrency es la respuesta tentadora, pero es la opción de pagar para mantener entornos calientes, que quedó descartada.", ["Provisioned concurrency funciona, pero mantiene los entornos inicializados de forma continua, algo por lo que el equipo no quiere pagar.", "La concurrencia reservada pone un tope al escalado y no afecta el tiempo de inicialización.", "Más espacio en /tmp no acelera la inicialización del runtime ni del código.", null]],
});
